const g=4,n="cong-nghe",h="Công nghệ lớp 4",i="internal",t="bvkp-15e4eeb8fb76",c=[{id:"hoa-cay-canh",title:"Hoa và cây cảnh quanh em",lessons:[{id:"cn4-loi-ich-hoa",title:"Lợi ích của hoa và cây cảnh",weeks:[1,2],learn:[{title:"Hoa và cây cảnh làm đẹp",text:"Hoa và cây cảnh được trồng để trang trí nhà cửa, trường học, công viên và đường phố.",example:"🌷 nhà · 🏫 trường · 🌳 công viên"},{title:"Cây xanh làm môi trường dễ chịu",text:"Cây xanh cho bóng mát, góp phần làm không khí trong lành và làm mát mắt.",example:"🌳 bóng mát · 🍃 không khí trong lành"},{title:"Niềm vui và thu nhập",text:"Hoa dùng làm quà tặng, trang trí ngày lễ, ngày Tết. Trồng hoa để bán còn đem lại thu nhập.",example:"💐 quà tặng · 🧧 ngày Tết · 💰 thu nhập"}],practice:[{questions:[{id:"cn4-loi-ich-hoa-01",type:"mc",q:"Hoa và cây cảnh thường được dùng để làm gì?",emoji:"🌷",explain:"Hoa và cây cảnh được trồng để trang trí, làm đẹp nhà cửa, trường học và phố phường.",options:["Làm đồ chơi điện","Trang trí, làm đẹp","Thay cho bàn ghế","Làm sách vở"],answer:1},{id:"cn4-loi-ich-hoa-02",type:"tf",q:"Cây xanh trồng trong nhà góp phần làm không khí thêm trong lành.",emoji:"🪴",explain:"Đúng. Cây xanh nhả khí ô-xi và làm cho không gian mát mắt, dễ chịu hơn.",answer:!0},{id:"cn4-loi-ich-hoa-03",type:"mc",q:"Ngày Nhà giáo Việt Nam, các bạn thường tặng thầy cô món quà gì?",emoji:"💐",explain:"Hoa là món quà đẹp, thể hiện lòng biết ơn và yêu quý thầy cô.",options:["Chiếc xẻng","Cái chổi","Hộp phấn cũ","Bó hoa tươi"],answer:3},{id:"cn4-loi-ich-hoa-04",type:"tf",q:"Hoa và cây cảnh chỉ có ích cho người giàu.",explain:"Sai. Ai cũng có thể trồng và chăm hoa, cây cảnh để làm đẹp nơi mình sống.",answer:!1},{id:"cn4-loi-ich-hoa-05",type:"multi",q:"Chọn những lợi ích của hoa và cây cảnh.",explain:"Hoa, cây cảnh làm đẹp, làm không khí trong lành và đem lại niềm vui; chúng không thay được bữa ăn.",options:["Làm đẹp nhà cửa","Làm không khí trong lành","Thay cho cơm ăn hằng ngày","Đem lại niềm vui"],answers:[0,1,3]},{id:"cn4-loi-ich-hoa-06",type:"fill",q:"Trồng hoa trên ban công giúp ngôi nhà thêm … .",emoji:"🏠",answer:["đẹp","xinh","xinh đẹp","tươi đẹp"],explain:"Hoa trên ban công làm ngôi nhà thêm đẹp và tươi vui."},{id:"cn4-loi-ich-hoa-07",type:"mc",q:"Dịp Tết, nhiều gia đình bày hoa, cây cảnh để làm gì?",emoji:"🧧",explain:"Ngày Tết, hoa và cây cảnh làm nhà cửa tươi vui, đón năm mới.",options:["Để đuổi muỗi","Để che cửa sổ","Để làm củi đun","Trang trí đón Tết"],answer:3},{id:"cn4-loi-ich-hoa-08",type:"tf",q:"Chăm sóc cây cảnh giúp em thư giãn và vui vẻ hơn.",emoji:"😊",explain:"Đúng. Ngắm hoa, chăm cây giúp em thấy thư thái và yêu thiên nhiên hơn.",answer:!0},{id:"cn4-loi-ich-hoa-09",type:"mc",q:"Hàng cây xanh hai bên đường có ích gì cho người đi đường?",emoji:"🌳",explain:"Cây xanh hai bên đường cho bóng mát và làm phố phường đẹp hơn.",options:["Làm đường trơn hơn","Làm xe chạy nhanh","Làm trời mưa nhiều","Cho bóng mát"],answer:3}]},{questions:[{id:"cn4-loi-ich-hoa-10",type:"match",q:"Nối nơi trồng hoa, cây cảnh với lợi ích của nó.",explain:"Mỗi nơi trồng cây đều được làm đẹp và dễ chịu hơn.",pairs:[["Sân trường","Thêm bóng mát"],["Bàn học","Mát mắt khi học"],["Ban công","Nhà thêm đẹp"]]},{id:"cn4-loi-ich-hoa-11",type:"mc",q:"Vì sao nhiều người đặt một chậu cây nhỏ trên bàn học?",emoji:"📚",explain:"Màu xanh của cây giúp mắt dịu lại sau khi đọc, viết lâu.",options:["Để che sách vở","Để mát mắt, dễ chịu","Để tưới thay nước uống","Để làm thước kẻ"],answer:1},{id:"cn4-loi-ich-hoa-12",type:"tf",q:"Trồng và bán hoa có thể đem lại thu nhập cho nhiều gia đình.",emoji:"💰",explain:"Đúng. Nhiều làng trồng hoa, cây cảnh để bán, nhất là dịp Tết.",answer:!0},{id:"cn4-loi-ich-hoa-13",type:"mc",q:"Lan treo giỏ hoa trước hiên nhà. Việc đó giúp gì cho ngôi nhà?",emoji:"🏡",explain:"Giỏ hoa làm hiên nhà thêm đẹp và tươi vui.",options:["Nhà tối hơn","Nhà ồn ào hơn","Nhà đẹp, tươi vui","Nhà bụi hơn"],answer:2},{id:"cn4-loi-ich-hoa-14",type:"multi",q:"Những nơi nào thường được trang trí bằng hoa, cây cảnh?",explain:"Hoa, cây cảnh làm đẹp công viên, trường học và các buổi lễ; không ai đặt cây vào ổ điện.",options:["Công viên","Trường học","Lễ khai giảng","Trong ổ điện"],answers:[0,1,2]},{id:"cn4-loi-ich-hoa-15",type:"tf",q:"Hoa chỉ để ngắm, không có loài hoa nào được dùng làm thực phẩm.",emoji:"🍵",explain:"Sai. Có loài hoa dùng được trong ăn uống, ví dụ người ta dùng hoa cúc để pha trà.",answer:!1},{id:"cn4-loi-ich-hoa-16",type:"fill",q:"Cây xanh giúp không khí thêm trong … .",emoji:"🌿",answer:["lành"],explain:"Cây xanh góp phần làm không khí trong lành."},{id:"cn4-loi-ich-hoa-17",type:"mc",q:"Lợi ích nào KHÔNG phải của hoa và cây cảnh?",explain:"Hoa và cây cảnh không thể sạc pin điện thoại.",options:["Làm đẹp cảnh quan","Tạo bóng mát","Sạc pin điện thoại","Làm quà tặng"],answer:2},{id:"cn4-loi-ich-hoa-18",type:"match",q:"Nối dịp với loài hoa hay được dùng.",explain:"Hoa đào, hoa mai là hoa Tết quen thuộc; ngày 20 tháng 11 học sinh tặng hoa thầy cô.",pairs:[["Tết ở miền Bắc","Hoa đào"],["Tết ở miền Nam","Hoa mai"],["Ngày 20 tháng 11","Bó hoa tặng cô"]]}]},{questions:[{id:"cn4-loi-ich-hoa-19",type:"mc",q:"Lớp em muốn sân trường mát và đẹp hơn. Cách nào phù hợp?",emoji:"🏫",explain:"Trồng thêm cây xanh giúp sân trường có bóng mát và đẹp hơn.",options:["Vứt rác ở gốc cây","Đổ thêm bê tông","Chặt bớt cây","Trồng thêm cây xanh"],answer:3},{id:"cn4-loi-ich-hoa-20",type:"mc",q:"Nhà Bình ở chung cư, không có sân. Bình có thể trồng hoa ở đâu?",emoji:"🏢",explain:"Trồng hoa trong chậu ở ban công vừa đẹp vừa không cản lối đi.",options:["Trong ổ điện","Giữa hành lang","Chậu ở ban công","Trong thang máy"],answer:2},{id:"cn4-loi-ich-hoa-21",type:"tf",q:"Bạn Minh ngắt trộm hoa trong công viên đem về nhà là việc làm đúng.",emoji:"🚫",explain:"Sai. Hoa trong công viên là của chung, cần giữ gìn để mọi người cùng ngắm.",answer:!1},{id:"cn4-loi-ich-hoa-22",type:"multi",q:"Em có thể làm gì để giữ gìn hoa, cây cảnh nơi công cộng?",explain:"Không bẻ cành, không giẫm bồn hoa và nhắc nhau giữ gìn là việc làm tốt.",options:["Không bẻ cành, ngắt hoa","Không giẫm lên bồn hoa","Vẽ bậy lên thân cây","Nhắc bạn bè cùng giữ gìn"],answers:[0,1,3]},{id:"cn4-loi-ich-hoa-23",type:"mc",q:"Hà muốn tặng bà một món quà tự làm. Món quà nào hợp lí?",emoji:"🎁",explain:"Chậu hoa tự trồng là món quà đẹp, có ý nghĩa và an toàn.",options:["Chậu hoa nhỏ tự trồng","Hộp diêm","Con dao sắc","Túi rác"],answer:0},{id:"cn4-loi-ich-hoa-24",type:"fill",q:"Người làm nghề trồng hoa để bán thường được gọi là người trồng … .",emoji:"👩‍🌾",answer:["hoa"],explain:"Người trồng hoa chăm sóc hoa để bán, làm đẹp cho cuộc sống."},{id:"cn4-loi-ich-hoa-25",type:"tf",q:"Đặt vài chậu cây xanh trong lớp học giúp lớp thêm sinh động.",emoji:"🪴",explain:"Đúng. Cây xanh giúp lớp học đẹp, mát mắt và gần gũi thiên nhiên hơn.",answer:!0},{id:"cn4-loi-ich-hoa-26",type:"mc",q:"Vì sao không nên giẫm lên bồn hoa ở công viên?",explain:"Giẫm lên bồn hoa làm gãy, dập cây và làm mất vẻ đẹp chung.",options:["Vì sẽ làm bẩn giày","Vì làm hỏng cây hoa","Vì hoa sẽ cắn chân","Vì bồn hoa rất cao"],answer:1}]}],challenge:{questions:[{id:"cn4-loi-ich-hoa-27",type:"mc",q:"Khu phố muốn đường làng thêm đẹp. Việc nào nên làm?",emoji:"🌼",explain:"Trồng hoa hai bên đường làm đường làng đẹp và sạch hơn.",options:["Trồng hoa hai bên đường","Đốt rác ven đường","Nhổ hết cỏ cây","Treo rác lên cây"],answer:0},{id:"cn4-loi-ich-hoa-28",type:"multi",q:"Hoa và cây cảnh có lợi ích gì cho tinh thần con người?",explain:"Ngắm hoa, chăm cây giúp con người thư giãn, vui vẻ và yêu thiên nhiên.",options:["Giúp thư giãn","Làm vui mắt","Làm ta giận dữ","Giúp yêu thiên nhiên"],answers:[0,1,3]},{id:"cn4-loi-ich-hoa-29",type:"tf",q:"Hoa và cây cảnh vừa làm đẹp vừa có thể đem lại thu nhập.",explain:"Đúng. Ngoài làm đẹp, trồng hoa, cây cảnh để bán giúp nhiều gia đình có thu nhập.",answer:!0},{id:"cn4-loi-ich-hoa-22",type:"multi",q:"Em có thể làm gì để giữ gìn hoa, cây cảnh nơi công cộng?",explain:"Không bẻ cành, không giẫm bồn hoa và nhắc nhau giữ gìn là việc làm tốt.",options:["Không bẻ cành, ngắt hoa","Không giẫm lên bồn hoa","Vẽ bậy lên thân cây","Nhắc bạn bè cùng giữ gìn"],answers:[0,1,3]},{id:"cn4-loi-ich-hoa-15",type:"tf",q:"Hoa chỉ để ngắm, không có loài hoa nào được dùng làm thực phẩm.",emoji:"🍵",explain:"Sai. Có loài hoa dùng được trong ăn uống, ví dụ người ta dùng hoa cúc để pha trà.",answer:!1},{id:"cn4-loi-ich-hoa-20",type:"mc",q:"Nhà Bình ở chung cư, không có sân. Bình có thể trồng hoa ở đâu?",emoji:"🏢",explain:"Trồng hoa trong chậu ở ban công vừa đẹp vừa không cản lối đi.",options:["Trong ổ điện","Giữa hành lang","Chậu ở ban công","Trong thang máy"],answer:2},{id:"cn4-loi-ich-hoa-18",type:"match",q:"Nối dịp với loài hoa hay được dùng.",explain:"Hoa đào, hoa mai là hoa Tết quen thuộc; ngày 20 tháng 11 học sinh tặng hoa thầy cô.",pairs:[["Tết ở miền Bắc","Hoa đào"],["Tết ở miền Nam","Hoa mai"],["Ngày 20 tháng 11","Bó hoa tặng cô"]]}]},summary:["Hoa và cây cảnh làm đẹp nhà cửa, trường học và nơi công cộng.","Cây xanh cho bóng mát và góp phần làm không khí trong lành.","Hoa, cây cảnh đem lại niềm vui, làm quà tặng và có thể đem lại thu nhập."]},{id:"cn4-loai-hoa",title:"Một số loài hoa phổ biến",weeks:[3,4],learn:[{title:"Hoa hồng, hoa cúc, hoa lan",text:"Hoa hồng có nhiều màu, thân có gai. Hoa cúc có nhiều cánh nhỏ, hay có màu vàng. Lan có rất nhiều loài, hoa đẹp.",example:"🌹 hồng · 🌼 cúc · 🌸 lan"},{title:"Hoa đào, hoa mai",text:"Hoa đào màu hồng nở dịp Tết ở miền Bắc. Hoa mai vàng, thường năm cánh, là hoa Tết ở miền Nam.",example:"🌸 đào – miền Bắc · 🌼 mai – miền Nam"},{title:"Hoa sen, hướng dương, hoa giấy",text:"Sen sống dưới ao, hồ, lá to gần tròn. Hướng dương có bông to cánh vàng. Hoa giấy cánh mỏng, hay leo giàn.",example:"🪷 sen · 🌻 hướng dương · 🌺 hoa giấy"}],practice:[{questions:[{id:"cn4-loai-hoa-01",type:"mc",q:"Loài hoa nào có gai ở thân?",emoji:"🌹",explain:"Thân cây hoa hồng có gai nhọn, khi cắt hoa cần cẩn thận.",options:["Hoa hồng","Hoa cúc","Hoa hướng dương","Hoa sen"],answer:0},{id:"cn4-loai-hoa-02",type:"mc",q:"Hoa sen mọc ở đâu?",emoji:"🪷",explain:"Sen sống ở nơi có nước như ao, hồ, đầm.",options:["Trên núi đá","Trong sa mạc","Dưới ao, hồ","Trên mái nhà"],answer:2},{id:"cn4-loai-hoa-03",type:"tf",q:"Hoa đào thường nở vào dịp Tết ở miền Bắc.",emoji:"🌸",explain:"Đúng. Hoa đào màu hồng là hoa Tết quen thuộc của miền Bắc.",answer:!0},{id:"cn4-loai-hoa-04",type:"mc",q:"Hoa mai vàng là hoa Tết quen thuộc của vùng nào?",emoji:"🌼",explain:"Ở miền Nam, nhà nhà chưng hoa mai vàng ngày Tết.",options:["Vùng Bắc Cực","Miền Bắc","Miền Nam","Dưới biển"],answer:2},{id:"cn4-loai-hoa-05",type:"match",q:"Nối tên hoa với đặc điểm của nó.",explain:"Sen sống dưới nước, hồng có gai, hướng dương có bông to màu vàng.",pairs:[["Hoa sen","Mọc dưới nước"],["Hoa hồng","Thân có gai"],["Hoa hướng dương","Hoa to, cánh vàng"]]},{id:"cn4-loai-hoa-06",type:"fill",q:"Bông hoa có tên gọi “hướng về Mặt Trời” là hoa hướng … .",emoji:"🌻",answer:["dương"],explain:"Hoa hướng dương có tên nghĩa là hướng về phía Mặt Trời."},{id:"cn4-loai-hoa-07",type:"tf",q:"Hoa cúc chỉ có một màu duy nhất là màu đỏ.",emoji:"🌼",explain:"Sai. Hoa cúc có nhiều màu như vàng, trắng, tím; màu vàng rất quen thuộc.",answer:!1},{id:"cn4-loai-hoa-08",type:"mc",q:"Hoa đào thường có màu gì?",emoji:"🌸",explain:"Hoa đào thường có màu hồng, nở rộ dịp Tết.",options:["Hồng","Xanh lá","Đen","Xám"],answer:0},{id:"cn4-loai-hoa-09",type:"tf",q:"Hoa giấy có cánh mỏng, nhiều màu và thường được trồng leo giàn.",emoji:"🌺",explain:"Đúng. Hoa giấy có cánh mỏng như giấy, hay được trồng cho leo giàn, leo cổng.",answer:!0}]},{questions:[{id:"cn4-loai-hoa-10",type:"mc",q:"Vì sao khi cắt hoa hồng nên đeo găng tay?",emoji:"🧤",explain:"Thân hoa hồng có gai nhọn, đeo găng tay để không bị gai đâm.",options:["Vì hoa rất nóng","Vì hoa có điện","Vì hoa rất nặng","Vì thân có gai"],answer:3},{id:"cn4-loai-hoa-11",type:"multi",q:"Những loài hoa nào thường được chưng dịp Tết?",explain:"Đào, mai, cúc là hoa Tết quen thuộc; sen nở chủ yếu vào mùa hè.",options:["Hoa đào","Hoa mai","Hoa cúc","Hoa sen"],answers:[0,1,2]},{id:"cn4-loai-hoa-12",type:"mc",q:"Lá sen có hình dạng thế nào?",emoji:"🍃",explain:"Lá sen to, gần tròn, nổi hoặc vươn lên trên mặt nước.",options:["To, gần tròn","Nhỏ như kim","Dài như sợi chỉ","Có gai nhọn"],answer:0},{id:"cn4-loai-hoa-13",type:"tf",q:"Giữa bông hoa hướng dương có rất nhiều hạt.",emoji:"🌻",explain:"Đúng. Phần giữa bông hướng dương chứa nhiều hạt, có thể dùng làm hạt giống.",answer:!0},{id:"cn4-loai-hoa-14",type:"match",q:"Nối loài hoa với nơi thích hợp để trồng.",explain:"Sen trồng dưới nước, hoa giấy cho leo giàn, nhiều loài lan trồng trong chậu treo.",pairs:[["Hoa sen","Ao, hồ"],["Hoa giấy","Giàn, cổng"],["Hoa lan","Chậu treo"]]},{id:"cn4-loai-hoa-15",type:"mc",q:"Mùa hè, em thấy ao làng nở đầy hoa. Đó có thể là hoa gì?",emoji:"☀️",explain:"Hoa sen nở nhiều vào mùa hè ở ao, hồ.",options:["Hoa đào","Hoa giấy","Hoa mai","Hoa sen"],answer:3},{id:"cn4-loai-hoa-16",type:"fill",q:"Hoa mai vàng thường có năm … hoa.",emoji:"🌼",answer:["cánh"],explain:"Bông mai vàng thường có năm cánh màu vàng."},{id:"cn4-loai-hoa-17",type:"tf",q:"Hoa lan có rất nhiều loài với nhiều màu sắc khác nhau.",emoji:"🌸",explain:"Đúng. Lan có rất nhiều loài, hoa có nhiều màu và hình dáng đẹp.",answer:!0},{id:"cn4-loai-hoa-18",type:"mc",q:"Hoa nào thường được trồng leo cổng, leo tường?",explain:"Hoa giấy có cành dài, dễ cho leo cổng, leo tường.",options:["Hoa giấy","Hoa cúc","Hoa sen","Hoa hướng dương"],answer:0}]},{questions:[{id:"cn4-loai-hoa-19",type:"mc",q:"Nhà Ngọc có một cái ao nhỏ. Ngọc nên trồng hoa gì ở ao?",emoji:"🪷",explain:"Sen là cây sống dưới nước nên hợp trồng ở ao.",options:["Hoa hồng","Hoa sen","Hoa mai","Hoa giấy"],answer:1},{id:"cn4-loai-hoa-20",type:"mc",q:"Tết này, nhà Phúc ở Hà Nội muốn chưng hoa truyền thống. Hoa nào hợp?",emoji:"🧧",explain:"Ở miền Bắc, cành đào hồng là hoa Tết truyền thống.",options:["Cành đào","Hoa sen","Hoa giấy","Hoa hướng dương"],answer:0},{id:"cn4-loai-hoa-21",type:"multi",q:"Chọn những câu nói đúng về cây hoa giấy.",explain:"Hoa giấy leo được cổng, thân có gai, cánh mỏng; nó không mọc dưới nước.",options:["Có thể leo cổng","Thân có gai","Mọc dưới nước","Cánh mỏng như giấy"],answers:[0,1,3]},{id:"cn4-loai-hoa-22",type:"tf",q:"Hoa hồng không có gai nên có thể cầm thân hoa thật chặt.",emoji:"🌹",explain:"Sai. Thân hoa hồng có gai, cầm chặt dễ bị đâm vào tay.",answer:!1},{id:"cn4-loai-hoa-23",type:"mc",q:"Nam muốn có hạt để gieo hoa hướng dương. Nam lấy hạt ở đâu?",emoji:"🌻",explain:"Hạt hướng dương nằm ở phần giữa bông hoa khi hoa đã già.",options:["Ở giữa bông hoa","Ở rễ cây","Ở lá cây","Ở chậu đất"],answer:0},{id:"cn4-loai-hoa-24",type:"match",q:"Nối hoa với dịp em hay thấy nó.",explain:"Đào, mai nở dịp Tết ở hai miền; sen nở nhiều vào mùa hè.",pairs:[["Hoa đào","Tết miền Bắc"],["Hoa mai","Tết miền Nam"],["Hoa sen","Mùa hè"]]},{id:"cn4-loai-hoa-25",type:"fill",q:"Loài hoa sống dưới ao, hồ, có lá to tròn là hoa … .",emoji:"🪷",answer:["sen"],explain:"Hoa sen sống dưới nước, lá to gần tròn."},{id:"cn4-loai-hoa-26",type:"tf",q:"Có thể trồng hoa sen trong chậu đất khô đặt trên bàn học.",explain:"Sai. Sen cần sống trong nước, không trồng trong chậu đất khô được.",answer:!1}]}],challenge:{questions:[{id:"cn4-loai-hoa-27",type:"mc",q:"Loài hoa nào vừa có thể trồng giàn vừa chịu được nắng tốt?",explain:"Hoa giấy ưa nắng, cành dài, thích hợp trồng giàn.",options:["Hoa giấy","Hoa sen","Hoa lan","Hoa đào"],answer:0},{id:"cn4-loai-hoa-28",type:"multi",q:"Chọn những câu nói đúng về hoa hướng dương.",explain:"Hướng dương có bông to, cánh vàng, giữa bông có hạt; nó mọc trên cạn.",options:["Bông hoa to","Cánh màu vàng","Mọc dưới nước","Giữa bông có hạt"],answers:[0,1,3]},{id:"cn4-loai-hoa-29",type:"tf",q:"Hoa đào và hoa mai đều là hoa thường chưng trong dịp Tết.",explain:"Đúng. Đào là hoa Tết miền Bắc, mai vàng là hoa Tết miền Nam.",answer:!0},{id:"cn4-loai-hoa-21",type:"multi",q:"Chọn những câu nói đúng về cây hoa giấy.",explain:"Hoa giấy leo được cổng, thân có gai, cánh mỏng; nó không mọc dưới nước.",options:["Có thể leo cổng","Thân có gai","Mọc dưới nước","Cánh mỏng như giấy"],answers:[0,1,3]},{id:"cn4-loai-hoa-26",type:"tf",q:"Có thể trồng hoa sen trong chậu đất khô đặt trên bàn học.",explain:"Sai. Sen cần sống trong nước, không trồng trong chậu đất khô được.",answer:!1},{id:"cn4-loai-hoa-11",type:"multi",q:"Những loài hoa nào thường được chưng dịp Tết?",explain:"Đào, mai, cúc là hoa Tết quen thuộc; sen nở chủ yếu vào mùa hè.",options:["Hoa đào","Hoa mai","Hoa cúc","Hoa sen"],answers:[0,1,2]},{id:"cn4-loai-hoa-24",type:"match",q:"Nối hoa với dịp em hay thấy nó.",explain:"Đào, mai nở dịp Tết ở hai miền; sen nở nhiều vào mùa hè.",pairs:[["Hoa đào","Tết miền Bắc"],["Hoa mai","Tết miền Nam"],["Hoa sen","Mùa hè"]]}]},summary:["Mỗi loài hoa có màu sắc, hình dáng và nơi sống riêng.","Hoa đào là hoa Tết miền Bắc, hoa mai vàng là hoa Tết miền Nam.","Sen sống dưới nước; hoa hồng và hoa giấy có gai, cần cẩn thận khi chạm vào."]},{id:"cn4-cay-canh",title:"Một số loại cây cảnh phổ biến",weeks:[5,6],learn:[{title:"Cây cảnh trong nhà",text:"Kim tiền có lá xanh bóng. Lưỡi hổ có lá dài, cứng, có vằn. Cả hai dễ trồng trong chậu trong nhà.",example:"🪴 kim tiền · 🐯 lưỡi hổ"},{title:"Cây leo và cây ưa râm",text:"Trầu bà là cây thân leo, hay trồng chậu treo. Vạn niên thanh có lá to, ưa nơi râm mát.",example:"🌿 trầu bà · 🍃 vạn niên thanh"},{title:"Cây chịu hạn",text:"Xương rồng có thân mọng nước, nhiều gai, cần ít nước và nhiều nắng. Chạm vào phải cẩn thận.",example:"🌵 ít nước · ☀️ nhiều nắng"}],practice:[{questions:[{id:"cn4-cay-canh-01",type:"mc",q:"Cây nào có thân mọng nước và nhiều gai?",emoji:"🌵",explain:"Xương rồng có thân mọng nước, nhiều gai, sống được nơi khô hạn.",options:["Cây xương rồng","Cây kim tiền","Cây vạn niên thanh","Cây trầu bà"],answer:0},{id:"cn4-cay-canh-02",type:"tf",q:"Cây xương rồng cần ít nước.",emoji:"🌵",explain:"Đúng. Xương rồng chịu hạn tốt, tưới quá nhiều dễ làm cây bị thối.",answer:!0},{id:"cn4-cay-canh-03",type:"mc",q:"Cây lưỡi hổ có lá như thế nào?",emoji:"🪴",explain:"Lá lưỡi hổ dài, cứng, mọc thẳng đứng, thường có vằn.",options:["Lá tròn nổi trên nước","Không có lá","Lá nhỏ như kim","Lá dài, cứng, mọc thẳng"],answer:3},{id:"cn4-cay-canh-04",type:"mc",q:"Cây trầu bà có thân thế nào?",emoji:"🌿",explain:"Trầu bà có thân leo, lá thường hình tim, hay trồng chậu treo.",options:["Không có thân","Thân có gai","Thân rất to","Thân leo"],answer:3},{id:"cn4-cay-canh-05",type:"match",q:"Nối tên cây cảnh với đặc điểm của nó.",explain:"Mỗi cây cảnh có đặc điểm riêng giúp em nhận ra nó.",pairs:[["Xương rồng","Thân có gai"],["Trầu bà","Thân leo"],["Lưỡi hổ","Lá dài, cứng"]]},{id:"cn4-cay-canh-06",type:"fill",q:"Cây xương rồng có rất nhiều … nhọn.",emoji:"🌵",answer:["gai"],explain:"Xương rồng có nhiều gai nhọn, cần cẩn thận khi chạm vào."},{id:"cn4-cay-canh-07",type:"tf",q:"Cây kim tiền có lá xanh bóng và thường được trồng trong chậu ở trong nhà.",emoji:"🪴",explain:"Đúng. Kim tiền có lá xanh bóng, dễ trồng trong chậu đặt trong nhà.",answer:!0},{id:"cn4-cay-canh-08",type:"mc",q:"Cây cảnh nào thường được trồng trong chậu treo, để thân rủ xuống?",explain:"Trầu bà có thân leo, rủ xuống đẹp khi trồng chậu treo.",options:["Cây đào","Cây xương rồng","Cây lưỡi hổ","Cây trầu bà"],answer:3},{id:"cn4-cay-canh-09",type:"tf",q:"Cây cảnh chỉ trồng được ở ngoài vườn, không trồng trong nhà được.",emoji:"🏠",explain:"Sai. Nhiều cây cảnh như kim tiền, lưỡi hổ, trầu bà trồng trong nhà được.",answer:!1}]},{questions:[{id:"cn4-cay-canh-10",type:"mc",q:"Vì sao cây xương rồng sống được ở nơi khô hạn?",emoji:"🏜️",explain:"Thân xương rồng mọng nước, trữ nước để dùng khi trời khô hạn.",options:["Vì có nhiều hoa","Vì lá rất to","Vì cây có rễ trên lá","Vì thân trữ được nước"],answer:3},{id:"cn4-cay-canh-11",type:"multi",q:"Những cây cảnh nào hợp đặt trong nhà?",explain:"Kim tiền, lưỡi hổ, trầu bà sống được trong nhà; sen phải sống dưới nước.",options:["Cây kim tiền","Cây lưỡi hổ","Cây trầu bà","Cây hoa sen"],answers:[0,1,2]},{id:"cn4-cay-canh-12",type:"tf",q:"Tưới cho cây xương rồng mỗi ngày thật nhiều nước giúp cây lớn nhanh.",emoji:"💧",explain:"Sai. Xương rồng cần ít nước, tưới nhiều dễ làm rễ và thân bị thối.",answer:!1},{id:"cn4-cay-canh-13",type:"mc",q:"Cây vạn niên thanh hợp đặt ở chỗ nào?",emoji:"🌿",explain:"Vạn niên thanh ưa nơi râm mát, ít nắng trực tiếp.",options:["Dưới nắng gắt","Trong tủ lạnh","Trong nồi nước sôi","Nơi râm mát"],answer:3},{id:"cn4-cay-canh-14",type:"match",q:"Nối cây cảnh với cách chăm sóc phù hợp.",explain:"Mỗi cây cần cách chăm sóc phù hợp với đặc điểm của nó.",pairs:[["Xương rồng","Tưới rất ít"],["Vạn niên thanh","Để nơi râm"],["Trầu bà","Cho leo, rủ"]]},{id:"cn4-cay-canh-15",type:"mc",q:"Cây cảnh được cắt tỉa, uốn thành dáng đẹp gọi là gì?",emoji:"🌳",explain:"Người ta cắt tỉa, uốn cây để có dáng đẹp, gọi là cây cảnh tạo dáng.",options:["Cây dại","Cây ăn quả","Cây lương thực","Cây cảnh tạo dáng"],answer:3},{id:"cn4-cay-canh-16",type:"fill",q:"Cây trầu bà có thân … nên hay trồng chậu treo.",emoji:"🌿",answer:["leo"],explain:"Trầu bà là cây thân leo, trồng chậu treo cho thân rủ xuống."},{id:"cn4-cay-canh-17",type:"tf",q:"Lá cây lưỡi hổ thường có vằn ngang trông như da hổ.",emoji:"🐯",explain:"Đúng. Lá lưỡi hổ có vằn, vì vậy cây có tên như vậy.",answer:!0},{id:"cn4-cay-canh-18",type:"mc",q:"Đâu là cây cảnh, không phải cây lương thực?",explain:"Lưỡi hổ trồng để làm cảnh; lúa, ngô, khoai là cây lương thực.",options:["Cây lưỡi hổ","Cây ngô","Cây lúa","Cây khoai"],answer:0}]},{questions:[{id:"cn4-cay-canh-19",type:"mc",q:"Bàn học của Khoa ít nắng. Khoa nên chọn cây nào?",emoji:"📚",explain:"Kim tiền nhỏ sống được trong nhà, ít nắng, hợp đặt bàn học.",options:["Cây xương rồng to","Cây kim tiền nhỏ","Cây hoa sen","Cây đào"],answer:1},{id:"cn4-cay-canh-20",type:"mc",q:"Nhà Thảo hay đi vắng, ít khi tưới cây. Cây nào phù hợp?",emoji:"🌵",explain:"Xương rồng chịu hạn, cần ít nước nên hợp với nhà ít tưới.",options:["Cây lúa","Cây hoa sen","Cây xương rồng","Cây rau muống"],answer:2},{id:"cn4-cay-canh-21",type:"tf",q:"Em có thể bứt lá cây cảnh cho vào miệng nhai thử.",emoji:"🚫",explain:"Sai. Lá của một số cây cảnh có thể gây ngứa hoặc hại sức khỏe, không cho vào miệng.",answer:!1},{id:"cn4-cay-canh-22",type:"multi",q:"Khi chơi gần chậu xương rồng, em nên làm gì?",explain:"Gai xương rồng dễ đâm vào tay, cần để chậu xa lối đi và nhắc nhau cẩn thận.",options:["Không chạm vào gai","Đặt chậu xa lối đi","Ôm chậu chạy nhảy","Nhắc em nhỏ cẩn thận"],answers:[0,1,3]},{id:"cn4-cay-canh-23",type:"mc",q:"Lá cây trầu bà bị cháy vàng vì để ngoài nắng gắt. Em nên làm gì?",emoji:"☀️",explain:"Trầu bà ưa nơi râm mát, chuyển cây vào chỗ ít nắng gắt.",options:["Phơi nắng thêm","Chuyển vào nơi râm","Đổ nước sôi vào","Bỏ cây vào tủ"],answer:1},{id:"cn4-cay-canh-24",type:"match",q:"Nối nơi đặt với cây cảnh phù hợp.",explain:"Chọn cây theo ánh sáng và chỗ đặt giúp cây sống khỏe.",pairs:[["Bậu cửa nhiều nắng","Xương rồng"],["Góc phòng ít nắng","Vạn niên thanh"],["Chậu treo hiên nhà","Trầu bà"]]},{id:"cn4-cay-canh-25",type:"fill",q:"Cây sống được nơi khô hạn, thân mọng nước là cây xương … .",emoji:"🌵",answer:["rồng"],explain:"Xương rồng có thân mọng nước, chịu hạn rất tốt."},{id:"cn4-cay-canh-26",type:"tf",q:"Mỗi loại cây cảnh cần lượng nước và ánh sáng khác nhau.",explain:"Đúng. Ví dụ xương rồng cần ít nước, nhiều nắng; vạn niên thanh ưa râm.",answer:!0}]}],challenge:{questions:[{id:"cn4-cay-canh-27",type:"mc",q:"Chậu xương rồng bị úng nước, thân mềm nhũn. Nguyên nhân có thể là gì?",emoji:"💧",explain:"Xương rồng cần ít nước; tưới nhiều làm cây úng, thối.",options:["Thiếu nước","Tưới quá nhiều","Có quá nhiều gai","Chậu quá đẹp"],answer:1},{id:"cn4-cay-canh-28",type:"multi",q:"Chọn những câu nói đúng về cây cảnh trong nhà.",explain:"Cây trong nhà làm phòng xanh hơn, cần ánh sáng phù hợp, chậu chắc chắn và vẫn cần tưới.",options:["Làm phòng thêm xanh","Cần ánh sáng phù hợp","Không bao giờ cần tưới","Cần đặt chậu chắc chắn"],answers:[0,1,3]},{id:"cn4-cay-canh-29",type:"tf",q:"Cây vạn niên thanh thích hợp với nơi nắng gắt cả ngày.",explain:"Sai. Vạn niên thanh ưa nơi râm mát, nắng gắt dễ làm cháy lá.",answer:!1},{id:"cn4-cay-canh-21",type:"tf",q:"Em có thể bứt lá cây cảnh cho vào miệng nhai thử.",emoji:"🚫",explain:"Sai. Lá của một số cây cảnh có thể gây ngứa hoặc hại sức khỏe, không cho vào miệng.",answer:!1},{id:"cn4-cay-canh-24",type:"match",q:"Nối nơi đặt với cây cảnh phù hợp.",explain:"Chọn cây theo ánh sáng và chỗ đặt giúp cây sống khỏe.",pairs:[["Bậu cửa nhiều nắng","Xương rồng"],["Góc phòng ít nắng","Vạn niên thanh"],["Chậu treo hiên nhà","Trầu bà"]]},{id:"cn4-cay-canh-14",type:"match",q:"Nối cây cảnh với cách chăm sóc phù hợp.",explain:"Mỗi cây cần cách chăm sóc phù hợp với đặc điểm của nó.",pairs:[["Xương rồng","Tưới rất ít"],["Vạn niên thanh","Để nơi râm"],["Trầu bà","Cho leo, rủ"]]},{id:"cn4-cay-canh-20",type:"mc",q:"Nhà Thảo hay đi vắng, ít khi tưới cây. Cây nào phù hợp?",emoji:"🌵",explain:"Xương rồng chịu hạn, cần ít nước nên hợp với nhà ít tưới.",options:["Cây lúa","Cây hoa sen","Cây xương rồng","Cây rau muống"],answer:2}]},summary:["Kim tiền, lưỡi hổ, trầu bà, vạn niên thanh, xương rồng là cây cảnh quen thuộc.","Mỗi cây cảnh cần lượng nước và ánh sáng riêng; xương rồng cần ít nước.","Không cho lá cây vào miệng và cẩn thận với cây có gai."]}]},{id:"trong-cay-trong-chau",title:"Trồng hoa và cây cảnh trong chậu",lessons:[{id:"cn4-chau-dat",title:"Chậu và đất trồng",weeks:[7,8],learn:[{title:"Chậu trồng cây",text:"Chậu làm bằng nhựa, sành, gỗ, xi măng hoặc đồ cũ tái sử dụng. Đáy chậu cần có lỗ thoát nước.",example:"🪴 nhựa · 🏺 sành · ♻️ chai nhựa cũ"},{title:"Đất trồng",text:"Đất trồng tốt là đất tơi xốp, thoáng khí, giữ ẩm và có chất dinh dưỡng. Có thể trộn thêm phân hữu cơ, xơ dừa.",example:"🟤 đất + 🌿 phân hữu cơ + 🥥 xơ dừa"},{title:"Chuẩn bị chậu",text:"Lót sỏi nhỏ ở đáy, cho đất vào, chừa một khoảng ở miệng chậu để tưới không tràn. Làm xong nhớ rửa tay.",example:"🪨 sỏi → 🟤 đất → 🧼 rửa tay"}],practice:[{questions:[{id:"cn4-chau-dat-01",type:"mc",q:"Đáy chậu trồng cây cần có gì?",emoji:"🪴",explain:"Lỗ thoát nước ở đáy chậu giúp nước thừa chảy ra, rễ không bị úng.",options:["Bóng đèn","Bánh xe","Nắp đậy kín","Lỗ thoát nước"],answer:3},{id:"cn4-chau-dat-02",type:"tf",q:"Chậu trồng cây có thể làm bằng nhựa, sành, gỗ hoặc xi măng.",emoji:"🏺",explain:"Đúng. Chậu được làm từ nhiều vật liệu như nhựa, sành, gỗ, xi măng.",answer:!0},{id:"cn4-chau-dat-03",type:"mc",q:"Đất trồng cây trong chậu tốt là đất thế nào?",emoji:"🟤",explain:"Đất tơi xốp giúp rễ dễ phát triển, giữ ẩm và thoáng khí.",options:["Cứng như đá","Tơi xốp","Toàn sỏi to","Lẫn nhiều rác"],answer:1},{id:"cn4-chau-dat-04",type:"fill",q:"Đất trồng cây cần tơi … , thoáng khí và giữ được ẩm.",emoji:"🌱",answer:["xốp"],explain:"Đất tơi xốp giúp rễ cây dễ len lỏi và hút nước."},{id:"cn4-chau-dat-05",type:"multi",q:"Chậu trồng cây có thể làm bằng những vật liệu nào?",explain:"Chậu thường làm bằng nhựa, sành, gỗ; giấy ăn bị mủn khi ướt nên không làm chậu được.",options:["Nhựa","Sành","Gỗ","Giấy ăn"],answers:[0,1,2]},{id:"cn4-chau-dat-06",type:"tf",q:"Chậu không có lỗ thoát nước thì nước thừa đọng lại, rễ dễ bị thối.",emoji:"💧",explain:"Đúng. Nước đọng lâu ở đáy chậu làm rễ cây bị úng và thối.",answer:!0},{id:"cn4-chau-dat-07",type:"mc",q:"Vì sao nên trộn thêm phân hữu cơ vào đất trồng?",emoji:"🌿",explain:"Phân hữu cơ bổ sung chất dinh dưỡng cho cây lớn khỏe.",options:["Thêm chất dinh dưỡng","Làm đất cứng lại","Làm chậu nặng hơn","Đất đổi sang màu xanh"],answer:0},{id:"cn4-chau-dat-08",type:"mc",q:"Xơ dừa, trấu hun thường được trộn vào đất để làm gì?",explain:"Xơ dừa, trấu hun giúp đất tơi xốp, thoáng khí và giữ ẩm.",options:["Cho đất tơi, thoáng","Làm đất bốc mùi","Đuổi chim","Làm đất nóng"],answer:0},{id:"cn4-chau-dat-09",type:"tf",q:"Có thể dùng chai nhựa cũ cắt đôi, đục lỗ ở đáy để làm chậu trồng cây.",emoji:"♻️",explain:"Đúng. Tái sử dụng chai nhựa làm chậu vừa tiết kiệm vừa bảo vệ môi trường.",answer:!0}]},{questions:[{id:"cn4-chau-dat-10",type:"mc",q:"Vì sao nên lót một ít sỏi nhỏ ở đáy chậu?",emoji:"🪨",explain:"Lớp sỏi nhỏ ở đáy chậu giúp nước thừa thoát ra dễ hơn.",options:["Giúp thoát nước tốt","Để cây ra quả","Để chậu đẹp hơn","Để đất hết màu"],answer:0},{id:"cn4-chau-dat-11",type:"match",q:"Nối vật liệu với tác dụng của nó khi trồng cây.",explain:"Mỗi vật liệu giúp cây trong chậu sống khỏe theo một cách.",pairs:[["Lỗ ở đáy chậu","Thoát nước thừa"],["Phân hữu cơ","Thêm dinh dưỡng"],["Xơ dừa","Đất tơi, giữ ẩm"]]},{id:"cn4-chau-dat-12",type:"mc",q:"Cây nhỏ nên trồng trong chậu cỡ nào?",emoji:"📏",explain:"Chọn chậu vừa với kích thước cây để cây phát triển cân đối.",options:["Cốc không đáy","Chậu thật to","Chậu vừa với cây","Chậu không lỗ"],answer:2},{id:"cn4-chau-dat-13",type:"tf",q:"Đất sét bết dính, khi khô thì nứt cứng là đất tốt nhất để trồng hoa trong chậu.",explain:"Sai. Đất quá bết dính, khô cứng làm rễ khó phát triển; nên dùng đất tơi xốp.",answer:!1},{id:"cn4-chau-dat-14",type:"multi",q:"Đất trồng hoa trong chậu cần có những đặc điểm nào?",explain:"Đất tốt tơi xốp, thoáng khí, có chất dinh dưỡng; mảnh thủy tinh nguy hiểm, phải loại bỏ.",options:["Tơi xốp","Thoáng khí","Có chất dinh dưỡng","Lẫn mảnh thủy tinh"],answers:[0,1,2]},{id:"cn4-chau-dat-15",type:"mc",q:"Chậu sành, chậu đất nung có ưu điểm gì?",emoji:"🏺",explain:"Chậu sành, đất nung khá thoáng và chắc, nhưng dễ vỡ nếu làm rơi.",options:["Rất nhẹ như giấy","Thoáng, chắc chắn","Không bao giờ vỡ","Tự tưới nước"],answer:1},{id:"cn4-chau-dat-16",type:"fill",q:"Nước thừa trong chậu thoát ra ngoài qua lỗ thoát … .",emoji:"💧",answer:["nước"],explain:"Lỗ thoát nước ở đáy chậu giúp nước thừa chảy ra."},{id:"cn4-chau-dat-17",type:"tf",q:"Chậu nhựa nhẹ, dễ di chuyển.",emoji:"🪴",explain:"Đúng. Chậu nhựa nhẹ nên dễ mang đi, dễ sắp xếp.",answer:!0},{id:"cn4-chau-dat-18",type:"mc",q:"Khi chọn đất trồng, em cần nhặt bỏ thứ gì?",explain:"Nhặt bỏ rác, mảnh vụn để đất sạch, an toàn khi trồng cây.",options:["Mảnh vụn, rác","Phân hữu cơ","Đất tơi xốp","Xơ dừa"],answer:0}]},{questions:[{id:"cn4-chau-dat-19",type:"mc",q:"Chậu cây của Tùng bị đọng nước, lá vàng úa. Tùng nên làm gì?",emoji:"🍂",explain:"Nước đọng làm úng rễ; cần thông lỗ thoát nước để nước thừa chảy ra.",options:["Kiểm tra lỗ thoát nước","Tưới thêm nước","Bịt kín đáy chậu","Đặt chậu vào chậu nước"],answer:0},{id:"cn4-chau-dat-20",type:"order",q:"Sắp xếp các bước chuẩn bị chậu trồng cây.",items:["Chọn chậu có lỗ thoát nước","Lót sỏi nhỏ ở đáy chậu","Cho đất tơi xốp vào chậu","Để mặt đất thấp hơn miệng chậu"],explain:"Chọn chậu, lót sỏi, cho đất vào và chừa khoảng trống ở miệng chậu để tưới không tràn."},{id:"cn4-chau-dat-21",type:"mc",q:"Vì sao không nên đổ đất đầy tràn miệng chậu?",explain:"Chừa một khoảng ở miệng chậu giúp khi tưới, nước và đất không tràn ra ngoài.",options:["Để tưới không tràn","Để cây ít rễ","Để đất bị khô","Để chậu nhẹ hơn"],answer:0},{id:"cn4-chau-dat-22",type:"tf",q:"Chậu sành rơi xuống đất bị vỡ, em nên tự dùng tay không nhặt mảnh vỡ thật nhanh.",emoji:"⚠️",explain:"Sai. Mảnh sành sắc dễ cứa tay; em nhờ người lớn dọn hoặc đeo găng, dùng chổi hót.",answer:!1},{id:"cn4-chau-dat-23",type:"multi",q:"Em có thể dùng đồ cũ nào làm chậu trồng cây nhỏ?",explain:"Chai, hộp, ca nhựa cũ dùng được (đục lỗ thoát nước); lon có cạnh sắc dễ gây đứt tay.",options:["Chai nhựa cũ","Hộp sữa chua nhựa","Lon sắt có cạnh sắc","Ca nhựa bị nứt đáy"],answers:[0,1,3]},{id:"cn4-chau-dat-24",type:"mc",q:"Lan muốn đất trong chậu tơi xốp hơn. Lan có thể trộn thêm gì?",emoji:"🥥",explain:"Xơ dừa giúp đất tơi xốp, thoáng khí và giữ ẩm tốt.",options:["Xơ dừa","Xi măng","Cát trộn keo","Túi ni lông"],answer:0},{id:"cn4-chau-dat-25",type:"fill",q:"Phân hữu cơ giúp bổ sung chất dinh … cho cây.",emoji:"🌱",answer:["dưỡng"],explain:"Phân hữu cơ cung cấp chất dinh dưỡng giúp cây lớn khỏe."},{id:"cn4-chau-dat-26",type:"tf",q:"Sau khi trộn đất và phân bón, em cần rửa tay sạch bằng xà phòng.",emoji:"🧼",explain:"Đúng. Rửa tay bằng xà phòng sau khi làm vườn giúp em giữ vệ sinh, phòng bệnh.",answer:!0}]}],challenge:{questions:[{id:"cn4-chau-dat-27",type:"match",q:"Nối vấn đề với cách khắc phục.",explain:"Biết nguyên nhân giúp em chọn cách khắc phục đúng.",pairs:[["Đất bết, khô cứng","Trộn xơ dừa"],["Chậu đọng nước","Thông lỗ đáy chậu"],["Đất nghèo dinh dưỡng","Thêm phân hữu cơ"]]},{id:"cn4-chau-dat-28",type:"mc",q:"Vì sao chậu cần có lỗ ở đáy?",explain:"Lỗ ở đáy chậu cho nước thừa thoát ra, rễ không bị úng.",options:["Để giun bò vào","Để rễ không bị úng","Để chậu nhẹ hơn","Để đất rơi hết ra"],answer:1},{id:"cn4-chau-dat-29",type:"tf",q:"Một chậu tốt chỉ cần đẹp, không cần quan tâm lỗ thoát nước.",explain:"Sai. Chậu cần có lỗ thoát nước thì cây mới sống khỏe.",answer:!1},{id:"cn4-chau-dat-19",type:"mc",q:"Chậu cây của Tùng bị đọng nước, lá vàng úa. Tùng nên làm gì?",emoji:"🍂",explain:"Nước đọng làm úng rễ; cần thông lỗ thoát nước để nước thừa chảy ra.",options:["Kiểm tra lỗ thoát nước","Tưới thêm nước","Bịt kín đáy chậu","Đặt chậu vào chậu nước"],answer:0},{id:"cn4-chau-dat-20",type:"order",q:"Sắp xếp các bước chuẩn bị chậu trồng cây.",items:["Chọn chậu có lỗ thoát nước","Lót sỏi nhỏ ở đáy chậu","Cho đất tơi xốp vào chậu","Để mặt đất thấp hơn miệng chậu"],explain:"Chọn chậu, lót sỏi, cho đất vào và chừa khoảng trống ở miệng chậu để tưới không tràn."},{id:"cn4-chau-dat-23",type:"multi",q:"Em có thể dùng đồ cũ nào làm chậu trồng cây nhỏ?",explain:"Chai, hộp, ca nhựa cũ dùng được (đục lỗ thoát nước); lon có cạnh sắc dễ gây đứt tay.",options:["Chai nhựa cũ","Hộp sữa chua nhựa","Lon sắt có cạnh sắc","Ca nhựa bị nứt đáy"],answers:[0,1,3]},{id:"cn4-chau-dat-13",type:"tf",q:"Đất sét bết dính, khi khô thì nứt cứng là đất tốt nhất để trồng hoa trong chậu.",explain:"Sai. Đất quá bết dính, khô cứng làm rễ khó phát triển; nên dùng đất tơi xốp.",answer:!1}]},summary:["Chậu trồng cây cần có lỗ thoát nước ở đáy.","Đất trồng tốt là đất tơi xốp, thoáng khí, giữ ẩm và có chất dinh dưỡng.","Cẩn thận với mảnh chậu vỡ và rửa tay sạch sau khi làm."]},{id:"cn4-dung-cu",title:"Dụng cụ trồng hoa, cây cảnh",weeks:[9,10],learn:[{title:"Dụng cụ làm đất",text:"Xẻng nhỏ dùng để xúc đất, đào hốc. Cào nhỏ dùng để xới đất cho tơi.",example:"🪏 xẻng nhỏ · 🍴 cào nhỏ"},{title:"Dụng cụ tưới và tỉa",text:"Bình tưới có vòi hoa sen giúp tưới nhẹ, đều. Bình phun sương làm ẩm lá. Kéo cắt cành dùng để tỉa cành, lá.",example:"🚿 bình tưới · 💦 phun sương · ✂️ kéo"},{title:"Dùng dụng cụ an toàn",text:"Đeo găng tay, không đùa nghịch với kéo. Làm xong rửa sạch, lau khô, cất dụng cụ và rửa tay.",example:"🧤 găng tay · 🧽 rửa sạch · 🧼 rửa tay"}],practice:[{questions:[{id:"cn4-dung-cu-01",type:"mc",q:"Dụng cụ nào dùng để xúc đất cho vào chậu?",emoji:"🪏",explain:"Xẻng nhỏ dùng để xúc đất, đào hốc trồng cây.",options:["Xẻng nhỏ","Kéo cắt cành","Bình tưới","Găng tay"],answer:0},{id:"cn4-dung-cu-02",type:"mc",q:"Bình tưới có vòi hoa sen giúp gì?",emoji:"🚿",explain:"Vòi hoa sen chia nước thành nhiều tia nhỏ, tưới nhẹ không làm dập cây.",options:["Tưới nhẹ, đều","Cắt cành","Xới đất","Đào hốc"],answer:0},{id:"cn4-dung-cu-03",type:"tf",q:"Găng tay giúp bảo vệ tay khi làm đất, trồng cây.",emoji:"🧤",explain:"Đúng. Găng tay giữ tay sạch và tránh gai, vật sắc.",answer:!0},{id:"cn4-dung-cu-04",type:"match",q:"Nối dụng cụ với công dụng của nó.",explain:"Mỗi dụng cụ có công dụng riêng khi trồng và chăm sóc cây.",pairs:[["Xẻng nhỏ","Xúc đất"],["Bình tưới","Tưới nước"],["Kéo cắt cành","Tỉa cành, lá"]]},{id:"cn4-dung-cu-05",type:"fill",q:"Khi làm đất, em nên đeo … tay để bảo vệ tay.",emoji:"🧤",answer:["găng"],explain:"Găng tay giúp bảo vệ tay khỏi bẩn, gai và vật sắc."},{id:"cn4-dung-cu-06",type:"mc",q:"Dụng cụ nào dùng để xới cho đất tơi quanh gốc cây?",explain:"Cào nhỏ (dĩa xới) dùng để xới nhẹ cho đất tơi, thoáng.",options:["Bình tưới","Cào nhỏ","Thước kẻ","Chổi lông gà"],answer:1},{id:"cn4-dung-cu-07",type:"tf",q:"Kéo cắt cành là dụng cụ sắc, cần dùng cẩn thận.",emoji:"✂️",explain:"Đúng. Kéo cắt cành có lưỡi sắc, em chỉ dùng khi có người lớn hướng dẫn.",answer:!0},{id:"cn4-dung-cu-08",type:"multi",q:"Những dụng cụ nào thường dùng khi trồng cây trong chậu?",explain:"Xẻng, bình tưới, găng tay là dụng cụ trồng cây; bút chì màu dùng để vẽ.",options:["Xẻng nhỏ","Bình tưới","Găng tay","Bút chì màu"],answers:[0,1,2]},{id:"cn4-dung-cu-09",type:"mc",q:"Bình phun sương thường dùng để làm gì?",emoji:"💦",explain:"Bình phun sương tạo hạt nước nhỏ để làm ẩm lá cây.",options:["Phun ẩm cho lá","Cắt rễ","Đào đất","Đập đất"],answer:0}]},{questions:[{id:"cn4-dung-cu-10",type:"tf",q:"Em có thể dùng kéo cắt cành để đùa nghịch với bạn.",emoji:"🚫",explain:"Sai. Kéo cắt cành rất sắc, đùa nghịch dễ gây đứt tay hoặc bị thương.",answer:!1},{id:"cn4-dung-cu-11",type:"mc",q:"Cây con mới gieo cần tưới bằng gì?",emoji:"🌱",explain:"Cây con rất yếu, tưới nhẹ bằng vòi hoa sen để không bị dập, trôi đất.",options:["Cả xô nước dội","Bình có vòi hoa sen","Vòi nước xịt mạnh","Nước đá lạnh"],answer:1},{id:"cn4-dung-cu-12",type:"mc",q:"Khi đưa kéo cho bạn, em nên làm thế nào?",emoji:"✂️",explain:"Cầm phía lưỡi kéo khép lại, đưa phần cán cho bạn để an toàn.",options:["Ném kéo sang bạn","Cầm lưỡi, đưa cán","Vừa chạy vừa đưa","Chĩa mũi vào bạn"],answer:1},{id:"cn4-dung-cu-13",type:"multi",q:"Sau khi làm vườn xong, em nên làm gì?",explain:"Rửa và cất dụng cụ gọn gàng, rửa tay sạch; để kéo trên ghế dễ gây đứt tay.",options:["Rửa sạch dụng cụ","Cất dụng cụ đúng chỗ","Rửa tay bằng xà phòng","Để kéo trên ghế"],answers:[0,1,2]},{id:"cn4-dung-cu-14",type:"order",q:"Sắp xếp việc em làm khi dùng dụng cụ trồng cây.",items:["Đeo găng tay","Dùng xẻng xúc đất vào chậu","Tưới nhẹ bằng bình tưới","Rửa và cất dụng cụ"],explain:"Đeo găng tay trước, làm đất, tưới cây rồi rửa, cất dụng cụ."},{id:"cn4-dung-cu-15",type:"tf",q:"Dụng cụ dính đất sau khi dùng nên được rửa sạch, lau khô rồi cất đi.",emoji:"🧽",explain:"Đúng. Rửa sạch, lau khô giúp dụng cụ bền, không bị gỉ.",answer:!0},{id:"cn4-dung-cu-16",type:"mc",q:"Vì sao không nên tưới cây con bằng vòi nước xịt mạnh?",explain:"Nước xịt mạnh làm cây con gãy, dập và làm trôi đất quanh gốc.",options:["Làm cây lớn quá nhanh","Làm nước bị bẩn","Làm chậu đổi màu","Làm dập cây, trôi đất"],answer:3},{id:"cn4-dung-cu-17",type:"fill",q:"Dụng cụ dùng để tưới nước cho cây gọi là bình … .",emoji:"🚿",answer:["tưới"],explain:"Bình tưới chứa nước, có vòi để tưới cho cây."},{id:"cn4-dung-cu-18",type:"mc",q:"Dụng cụ nào em cần nhờ người lớn giúp khi dùng?",explain:"Kéo cắt cành sắc, em cần người lớn hướng dẫn hoặc giúp đỡ.",options:["Kéo cắt cành","Găng tay","Bình phun sương","Khăn lau"],answer:0}]},{questions:[{id:"cn4-dung-cu-19",type:"mc",q:"Minh muốn tỉa bớt lá úa của chậu hoa. Minh nên làm gì?",emoji:"✂️",explain:"Tỉa lá cần dụng cụ sắc, Minh nhờ người lớn giúp hoặc hướng dẫn.",options:["Dùng dao bếp tự cắt","Nhờ người lớn dùng kéo","Giật mạnh cả cành","Để lá úa mãi"],answer:1},{id:"cn4-dung-cu-20",type:"tf",q:"Để xẻng nằm giữa lối đi sau khi làm vườn là việc làm an toàn.",emoji:"⚠️",explain:"Sai. Để dụng cụ giữa lối đi dễ làm người khác vấp ngã, cần cất đúng chỗ.",answer:!1},{id:"cn4-dung-cu-21",type:"match",q:"Nối việc cần làm với dụng cụ phù hợp.",explain:"Chọn đúng dụng cụ giúp làm việc nhanh và an toàn.",pairs:[["Làm ẩm lá","Bình phun sương"],["Xới đất quanh gốc","Cào nhỏ"],["Bảo vệ tay","Găng tay"]]},{id:"cn4-dung-cu-22",type:"multi",q:"Ngọc chuẩn bị gieo hạt hoa. Ngọc cần chuẩn bị những gì?",explain:"Gieo hạt cần chậu đất, hạt giống, bình tưới; bàn là không dùng khi trồng cây.",options:["Chậu có đất","Hạt giống","Bình tưới","Bàn là điện"],answers:[0,1,2]},{id:"cn4-dung-cu-23",type:"mc",q:"Bạn Dũng dùng xẻng xong rồi vứt ở sân. Em nên nhắc bạn điều gì?",explain:"Dụng cụ cần được rửa sạch và cất đúng nơi để bền và an toàn.",options:["Đem xẻng đi chơi","Ném xẻng lên cao","Cứ để ngoài mưa","Rửa và cất xẻng"],answer:3},{id:"cn4-dung-cu-24",type:"tf",q:"Em nên rửa tay bằng xà phòng sau khi dùng dụng cụ làm vườn.",emoji:"🧼",explain:"Đúng. Tay dính đất, phân bón cần được rửa sạch để không bị bệnh.",answer:!0},{id:"cn4-dung-cu-25",type:"fill",q:"Kéo cắt cành có lưỡi rất … nên phải dùng cẩn thận.",emoji:"✂️",answer:["sắc","bén"],explain:"Lưỡi kéo sắc dễ gây đứt tay nếu dùng không cẩn thận."},{id:"cn4-dung-cu-26",type:"mc",q:"Trời nắng to, em muốn làm ẩm lá cây trầu bà. Dụng cụ nào phù hợp nhất?",explain:"Bình phun sương phun hạt nước nhỏ làm ẩm lá mà không làm úng gốc.",options:["Xẻng nhỏ","Kéo cắt cành","Bình phun sương","Cào nhỏ"],answer:2}]}],challenge:{questions:[{id:"cn4-dung-cu-27",type:"order",q:"Sắp xếp các việc sau khi làm vườn xong.",items:["Rửa sạch dụng cụ","Lau khô dụng cụ","Cất dụng cụ đúng chỗ","Rửa tay bằng xà phòng"],explain:"Rửa, lau khô và cất dụng cụ, cuối cùng rửa tay sạch."},{id:"cn4-dung-cu-28",type:"mc",q:"Vì sao nên lau khô xẻng sắt trước khi cất?",explain:"Xẻng sắt để ướt lâu dễ bị gỉ, lau khô giúp dụng cụ bền hơn.",options:["Để xẻng không bị gỉ","Để xẻng đổi màu","Để xẻng sắc hơn","Để xẻng nặng hơn"],answer:0},{id:"cn4-dung-cu-29",type:"multi",q:"Việc nào giúp em dùng dụng cụ làm vườn an toàn?",explain:"Đeo găng, không đùa với kéo, cất gọn dụng cụ giúp em an toàn.",options:["Đeo găng tay","Không đùa nghịch với kéo","Cất dụng cụ gọn gàng","Chĩa kéo vào bạn"],answers:[0,1,2]},{id:"cn4-dung-cu-19",type:"mc",q:"Minh muốn tỉa bớt lá úa của chậu hoa. Minh nên làm gì?",emoji:"✂️",explain:"Tỉa lá cần dụng cụ sắc, Minh nhờ người lớn giúp hoặc hướng dẫn.",options:["Dùng dao bếp tự cắt","Nhờ người lớn dùng kéo","Giật mạnh cả cành","Để lá úa mãi"],answer:1},{id:"cn4-dung-cu-26",type:"mc",q:"Trời nắng to, em muốn làm ẩm lá cây trầu bà. Dụng cụ nào phù hợp nhất?",explain:"Bình phun sương phun hạt nước nhỏ làm ẩm lá mà không làm úng gốc.",options:["Xẻng nhỏ","Kéo cắt cành","Bình phun sương","Cào nhỏ"],answer:2},{id:"cn4-dung-cu-12",type:"mc",q:"Khi đưa kéo cho bạn, em nên làm thế nào?",emoji:"✂️",explain:"Cầm phía lưỡi kéo khép lại, đưa phần cán cho bạn để an toàn.",options:["Ném kéo sang bạn","Cầm lưỡi, đưa cán","Vừa chạy vừa đưa","Chĩa mũi vào bạn"],answer:1},{id:"cn4-dung-cu-21",type:"match",q:"Nối việc cần làm với dụng cụ phù hợp.",explain:"Chọn đúng dụng cụ giúp làm việc nhanh và an toàn.",pairs:[["Làm ẩm lá","Bình phun sương"],["Xới đất quanh gốc","Cào nhỏ"],["Bảo vệ tay","Găng tay"]]}]},summary:["Xẻng, cào nhỏ, bình tưới, bình phun sương, kéo, găng tay là dụng cụ trồng cây.","Kéo cắt cành rất sắc, chỉ dùng khi có người lớn hướng dẫn.","Làm xong, rửa sạch, cất dụng cụ đúng chỗ và rửa tay bằng xà phòng."]},{id:"cn4-gieo-hat",title:"Gieo hạt trong chậu",weeks:[11,12],learn:[{title:"Chọn hạt giống",text:"Chọn hạt chắc, mẩy, không sâu mọt, không nấm mốc. Một số hạt được ngâm nước ấm để nhanh nảy mầm.",example:"🌰 chắc, mẩy ✅ · 🐛 sâu mọt ❌"},{title:"Các bước gieo hạt",text:"Cho đất vào chậu, tạo lỗ nông, gieo hạt thưa, phủ lớp đất mỏng rồi tưới nhẹ.",example:"🟤 đất → 🕳️ lỗ nông → 🌰 hạt → 🚿 tưới nhẹ"},{title:"Sau khi gieo",text:"Đặt chậu nơi thoáng, đủ ánh sáng; giữ đất ẩm nhưng không úng. Không cho hạt giống vào miệng.",example:"☀️ đủ sáng · 💧 đủ ẩm · 🚫 không ăn hạt"}],practice:[{questions:[{id:"cn4-gieo-hat-01",type:"mc",q:"Hạt giống tốt để gieo là hạt thế nào?",emoji:"🌰",explain:"Hạt chắc, mẩy, không sâu mọt dễ nảy mầm và cho cây khỏe.",options:["Lép, nhỏ","Bị mọt","Chắc, mẩy","Bị mốc"],answer:2},{id:"cn4-gieo-hat-02",type:"tf",q:"Gieo hạt quá sâu làm hạt khó nảy mầm lên khỏi mặt đất.",emoji:"🌱",explain:"Đúng. Hạt nhỏ chỉ nên gieo nông và phủ lớp đất mỏng.",answer:!0},{id:"cn4-gieo-hat-03",type:"order",q:"Sắp xếp các bước gieo hạt trong chậu.",items:["Cho đất vào chậu","Tạo lỗ nông trên mặt đất","Gieo hạt vào lỗ","Phủ lớp đất mỏng","Tưới nhẹ"],explain:"Chuẩn bị đất, tạo lỗ, gieo hạt, phủ đất mỏng rồi tưới nhẹ."},{id:"cn4-gieo-hat-04",type:"mc",q:"Sau khi gieo hạt, em tưới nước thế nào?",emoji:"🚿",explain:"Tưới nhẹ cho đất đủ ẩm, không làm trôi hạt.",options:["Không bao giờ tưới","Dội cả xô nước","Tưới nhẹ, vừa ẩm","Tưới nước nóng"],answer:2},{id:"cn4-gieo-hat-05",type:"fill",q:"Hạt cần nước, không khí và nhiệt độ thích hợp để nảy … .",emoji:"🌱",answer:["mầm"],explain:"Đủ nước, không khí và nhiệt độ phù hợp thì hạt mới nảy mầm."},{id:"cn4-gieo-hat-06",type:"tf",q:"Nên gieo thật nhiều hạt chen chúc nhau trong một chậu nhỏ.",explain:"Sai. Gieo quá dày làm cây con chen chúc, thiếu chỗ và thiếu ánh sáng.",answer:!1},{id:"cn4-gieo-hat-07",type:"mc",q:"Hạt mới nảy mầm, mầm non sẽ mọc lên từ đâu?",emoji:"🌱",explain:"Hạt nằm trong đất, khi nảy mầm thì mầm non nhú lên khỏi mặt đất.",options:["Từ trên lá","Từ dưới đất","Từ miệng bình tưới","Từ thành chậu"],answer:1},{id:"cn4-gieo-hat-08",type:"multi",q:"Hạt cần những điều kiện nào để nảy mầm?",explain:"Hạt cần nước, không khí và nhiệt độ thích hợp; tiếng nhạc không cần thiết.",options:["Nước","Không khí","Nhiệt độ thích hợp","Tiếng nhạc to"],answers:[0,1,2]},{id:"cn4-gieo-hat-09",type:"tf",q:"Hạt bị mọt, bị mốc vẫn là hạt giống tốt nhất để gieo.",emoji:"🚫",explain:"Sai. Hạt sâu mọt, nấm mốc khó nảy mầm, nên chọn hạt chắc, mẩy.",answer:!1}]},{questions:[{id:"cn4-gieo-hat-10",type:"mc",q:"Vì sao một số hạt được ngâm nước ấm trước khi gieo?",emoji:"♨️",explain:"Ngâm nước ấm giúp vỏ hạt mềm, hạt hút nước và nhanh nảy mầm hơn.",options:["Để hạt to bằng quả","Để hạt đổi màu","Để đuổi kiến","Để nhanh nảy mầm"],answer:3},{id:"cn4-gieo-hat-11",type:"mc",q:"Chậu vừa gieo hạt nên đặt ở đâu?",emoji:"☀️",explain:"Nơi thoáng, có ánh sáng giúp cây con mọc lên khỏe.",options:["Nơi thoáng, đủ sáng","Trong tủ kín","Dưới gầm giường","Trong túi ni lông buộc kín"],answer:0},{id:"cn4-gieo-hat-12",type:"tf",q:"Sau khi gieo, cần giữ cho đất luôn ẩm nhưng không bị úng nước.",emoji:"💧",explain:"Đúng. Đất ẩm vừa phải giúp hạt nảy mầm, úng nước làm hạt bị thối.",answer:!0},{id:"cn4-gieo-hat-13",type:"match",q:"Nối việc làm với lí do.",explain:"Mỗi việc làm khi gieo hạt đều có lí do riêng giúp cây mọc khỏe.",pairs:[["Phủ đất mỏng","Mầm dễ nhú lên"],["Tưới nhẹ","Không trôi hạt"],["Gieo thưa","Cây đủ chỗ lớn"]]},{id:"cn4-gieo-hat-14",type:"mc",q:"Vì sao tưới mạnh sau khi gieo hạt là không tốt?",explain:"Tưới mạnh làm trôi lớp đất phủ và cuốn hạt đi.",options:["Hạt nảy mầm quá nhanh","Chậu bị nhẹ đi","Hạt bị trôi, lộ ra","Đất thơm hơn"],answer:2},{id:"cn4-gieo-hat-15",type:"fill",q:"Không nên gieo hạt quá dày mà nên gieo … .",emoji:"🌱",answer:["thưa"],explain:"Gieo thưa giúp mỗi cây con có đủ chỗ và ánh sáng để lớn."},{id:"cn4-gieo-hat-16",type:"tf",q:"Chậu gieo hạt đặt trong tủ tối, đóng kín sẽ giúp cây con lớn khỏe.",explain:"Sai. Cây con cần ánh sáng và không khí; để trong tủ kín cây yếu, vàng úa.",answer:!1},{id:"cn4-gieo-hat-17",type:"multi",q:"Những hạt nào là hạt tốt để gieo?",explain:"Hạt chắc, mẩy, nguyên vỏ, không sâu mọt là hạt tốt; hạt mốc nên bỏ đi.",options:["Hạt chắc, mẩy","Hạt không sâu mọt","Hạt bị mốc xanh","Hạt còn nguyên vỏ"],answers:[0,1,3]},{id:"cn4-gieo-hat-18",type:"mc",q:"Gieo hạt xong, sau vài ngày em thấy gì nếu hạt nảy mầm?",emoji:"🌱",explain:"Khi hạt nảy mầm, em thấy mầm xanh nhỏ nhú lên khỏi mặt đất.",options:["Hạt biến thành đá","Chậu nở hoa ngay","Mầm xanh nhú lên","Đất đổi màu đỏ"],answer:2}]},{questions:[{id:"cn4-gieo-hat-19",type:"mc",q:"An gieo hạt nhưng tưới quá nhiều, đất luôn sũng nước. Điều gì dễ xảy ra?",emoji:"💧",explain:"Đất sũng nước làm hạt thiếu không khí và dễ bị thối.",options:["Hạt bị thối","Hạt mọc thật nhanh","Chậu ra quả","Đất khô nứt"],answer:0},{id:"cn4-gieo-hat-20",type:"mc",q:"Hạt đã gieo một tuần mà đất khô nứt, chưa nảy mầm. Nguyên nhân có thể là gì?",emoji:"🏜️",explain:"Đất khô nứt là thiếu nước, hạt không đủ ẩm để nảy mầm.",options:["Thiếu nước","Thừa nước","Chậu quá đẹp","Hạt quá chắc"],answer:0},{id:"cn4-gieo-hat-21",type:"order",q:"Sắp xếp các bước chọn và chuẩn bị hạt giống.",items:["Chọn hạt chắc, mẩy","Loại bỏ hạt lép, mọt","Ngâm hạt nếu cần","Đem hạt đi gieo"],explain:"Chọn hạt tốt, bỏ hạt xấu, ngâm nếu loại hạt đó cần rồi mới gieo."},{id:"cn4-gieo-hat-22",type:"tf",q:"Em có thể bỏ hạt giống vào miệng nếm thử khi gieo.",emoji:"🚫",explain:"Sai. Hạt giống có thể đã được xử lí thuốc, không được cho vào miệng.",answer:!1},{id:"cn4-gieo-hat-23",type:"multi",q:"Chậu hạt mới gieo của Hà mọc lên yếu, vàng. Hà nên làm gì?",explain:"Cây con cần đủ ánh sáng, đủ ẩm và không úng nước; tủ kín làm cây yếu hơn.",options:["Đặt chậu nơi đủ sáng","Tưới vừa đủ ẩm","Cất chậu vào tủ kín","Kiểm tra lỗ thoát nước"],answers:[0,1,3]},{id:"cn4-gieo-hat-24",type:"mc",q:"Hạt rất nhỏ như hạt hoa mười giờ nên gieo thế nào?",emoji:"🌸",explain:"Hạt nhỏ nên rắc đều trên mặt đất rồi phủ một lớp đất mỏng.",options:["Thả vào nước sôi","Chôn thật sâu","Gieo cả nắm một chỗ","Rắc đều, phủ đất mỏng"],answer:3},{id:"cn4-gieo-hat-25",type:"fill",q:"Sau khi gieo hạt, em phủ lên trên một lớp … mỏng.",emoji:"🟤",answer:["đất"],explain:"Lớp đất mỏng giữ ẩm cho hạt mà mầm vẫn nhú lên được."},{id:"cn4-gieo-hat-26",type:"tf",q:"Khi gieo hạt, đeo găng tay và rửa tay sau khi làm là việc làm đúng.",emoji:"🧤",explain:"Đúng. Đeo găng tay và rửa tay giúp em giữ vệ sinh, an toàn.",answer:!0}]}],challenge:{questions:[{id:"cn4-gieo-hat-27",type:"match",q:"Nối hiện tượng với nguyên nhân có thể.",explain:"Quan sát chậu hạt giúp em tìm ra nguyên nhân và chăm sóc đúng.",pairs:[["Đất khô nứt","Thiếu nước"],["Hạt bị thối","Tưới quá nhiều"],["Cây con vàng yếu","Thiếu ánh sáng"]]},{id:"cn4-gieo-hat-28",type:"mc",q:"Vì sao không gieo hạt quá dày trong một chậu?",explain:"Gieo dày làm cây con chen chúc, tranh nhau ánh sáng và chất dinh dưỡng.",options:["Hạt mọc nhanh hơn","Cây chen chúc, yếu","Chậu sẽ nhẹ đi","Đất nhiều chất hơn"],answer:1},{id:"cn4-gieo-hat-29",type:"tf",q:"Sau khi gieo hạt, chỉ cần tưới đúng một lần rồi không bao giờ tưới nữa.",explain:"Sai. Cần giữ đất đủ ẩm bằng cách tưới nhẹ hằng ngày hoặc khi đất khô.",answer:!1},{id:"cn4-gieo-hat-03",type:"order",q:"Sắp xếp các bước gieo hạt trong chậu.",items:["Cho đất vào chậu","Tạo lỗ nông trên mặt đất","Gieo hạt vào lỗ","Phủ lớp đất mỏng","Tưới nhẹ"],explain:"Chuẩn bị đất, tạo lỗ, gieo hạt, phủ đất mỏng rồi tưới nhẹ."},{id:"cn4-gieo-hat-19",type:"mc",q:"An gieo hạt nhưng tưới quá nhiều, đất luôn sũng nước. Điều gì dễ xảy ra?",emoji:"💧",explain:"Đất sũng nước làm hạt thiếu không khí và dễ bị thối.",options:["Hạt bị thối","Hạt mọc thật nhanh","Chậu ra quả","Đất khô nứt"],answer:0},{id:"cn4-gieo-hat-23",type:"multi",q:"Chậu hạt mới gieo của Hà mọc lên yếu, vàng. Hà nên làm gì?",explain:"Cây con cần đủ ánh sáng, đủ ẩm và không úng nước; tủ kín làm cây yếu hơn.",options:["Đặt chậu nơi đủ sáng","Tưới vừa đủ ẩm","Cất chậu vào tủ kín","Kiểm tra lỗ thoát nước"],answers:[0,1,3]},{id:"cn4-gieo-hat-22",type:"tf",q:"Em có thể bỏ hạt giống vào miệng nếm thử khi gieo.",emoji:"🚫",explain:"Sai. Hạt giống có thể đã được xử lí thuốc, không được cho vào miệng.",answer:!1}]},summary:["Chọn hạt chắc, mẩy, không sâu mọt để gieo.","Gieo hạt thưa, nông, phủ lớp đất mỏng và tưới nhẹ.","Đặt chậu nơi thoáng, đủ sáng và giữ đất đủ ẩm."]},{id:"cn4-trong-cay-con",title:"Trồng cây con trong chậu",weeks:[13,14],learn:[{title:"Chọn cây con",text:"Chọn cây con khỏe: lá xanh, thân thẳng, không sâu bệnh. Lấy cây ra nhẹ nhàng, giữ nguyên bầu đất.",example:"🌱 lá xanh ✅ · 🥀 héo úa ❌"},{title:"Các bước trồng",text:"Cho đất vào chậu, tạo hốc, đặt cây thẳng giữa chậu, lấp đất, ấn nhẹ quanh gốc rồi tưới nhẹ.",example:"🟤 đất → 🕳️ hốc → 🌱 cây → ✋ ấn nhẹ → 🚿 tưới"},{title:"Sau khi trồng",text:"Đặt chậu nơi râm mát vài ngày cho cây bén rễ, rồi mới đưa ra chỗ có nắng. Theo dõi cây hằng ngày.",example:"⛱️ râm mát → ☀️ đủ nắng"}],practice:[{questions:[{id:"cn4-trong-cay-con-01",type:"mc",q:"Cây con tốt để trồng là cây thế nào?",emoji:"🌱",explain:"Cây con khỏe có lá xanh, thân thẳng, không sâu bệnh.",options:["Rễ bị thối","Lá héo úa","Gãy ngọn","Lá xanh, khỏe"],answer:3},{id:"cn4-trong-cay-con-02",type:"order",q:"Sắp xếp các bước trồng cây con trong chậu.",items:["Cho đất vào chậu","Tạo hốc ở giữa chậu","Đặt cây con thẳng vào hốc","Lấp đất, ấn nhẹ quanh gốc","Tưới nhẹ quanh gốc"],explain:"Chuẩn bị đất, tạo hốc, đặt cây, lấp đất ấn nhẹ rồi tưới nước."},{id:"cn4-trong-cay-con-03",type:"tf",q:"Khi trồng, cần đặt cây con thẳng đứng ở giữa chậu.",emoji:"🪴",explain:"Đúng. Cây đặt thẳng, ở giữa chậu sẽ đứng vững và lớn cân đối.",answer:!0},{id:"cn4-trong-cay-con-04",type:"mc",q:"Lấp đất xong, em làm gì quanh gốc cây?",emoji:"✋",explain:"Ấn nhẹ đất quanh gốc giúp cây đứng vững, rễ tiếp xúc với đất.",options:["Giẫm mạnh lên","Đào đất ra","Ấn nhẹ đất","Đổ cát vào lá"],answer:2},{id:"cn4-trong-cay-con-05",type:"fill",q:"Sau khi trồng cây con, em … nhẹ nước quanh gốc.",emoji:"🚿",answer:["tưới"],explain:"Tưới nhẹ quanh gốc giúp đất ẩm, cây con nhanh bén rễ."},{id:"cn4-trong-cay-con-06",type:"tf",q:"Cây con mới trồng nên đặt ngay dưới nắng gắt buổi trưa.",emoji:"☀️",explain:"Sai. Cây con mới trồng còn yếu, nên đặt nơi râm mát vài ngày.",answer:!1},{id:"cn4-trong-cay-con-07",type:"multi",q:"Cây con khỏe có những đặc điểm nào?",explain:"Cây con khỏe có lá xanh, thân thẳng, không sâu bệnh.",options:["Lá xanh tươi","Thân thẳng","Không sâu bệnh","Lá bị sâu ăn"],answers:[0,1,2]},{id:"cn4-trong-cay-con-08",type:"mc",q:"Vì sao nên giữ nguyên bầu đất quanh rễ khi trồng cây con?",emoji:"🟤",explain:"Giữ bầu đất giúp rễ không bị đứt, cây nhanh bén rễ hơn.",options:["Để chậu nặng hơn","Để cây thấp lại","Để rễ không tổn thương","Để lá đổi màu"],answer:2},{id:"cn4-trong-cay-con-09",type:"tf",q:"Có thể trồng cây con trong chậu không có lỗ thoát nước.",explain:"Sai. Chậu cần lỗ thoát nước để rễ cây con không bị úng.",answer:!1}]},{questions:[{id:"cn4-trong-cay-con-10",type:"mc",q:"Vì sao cây con mới trồng nên để nơi râm mát vài ngày?",emoji:"⛱️",explain:"Rễ cây mới trồng cần thời gian bén vào đất; nắng gắt dễ làm cây héo.",options:["Để cây ngủ đông","Để cây kịp bén rễ","Để đất khô nứt","Để lá rụng hết"],answer:1},{id:"cn4-trong-cay-con-11",type:"match",q:"Nối bước trồng cây với lí do.",explain:"Mỗi bước trồng cây con đều giúp cây sống khỏe.",pairs:[["Tạo hốc giữa chậu","Có chỗ đặt rễ"],["Ấn nhẹ quanh gốc","Cây đứng vững"],["Tưới nhẹ","Đất ẩm, bén rễ"]]},{id:"cn4-trong-cay-con-12",type:"tf",q:"Lấy cây con ra khỏi bầu, nên cầm thật chặt ngọn cây rồi giật mạnh.",explain:"Sai. Giật mạnh làm gãy cây, đứt rễ; cần nhẹ nhàng lấy cả bầu đất.",answer:!1},{id:"cn4-trong-cay-con-13",type:"mc",q:"Hốc trồng cây con cần sâu thế nào?",explain:"Hốc vừa đủ chứa bầu rễ giúp cây đứng vững, không bị vùi ngọn.",options:["Thật rộng hết chậu","Sâu tới đáy chậu","Chỉ vài hạt đất","Vừa đủ chứa bầu rễ"],answer:3},{id:"cn4-trong-cay-con-14",type:"multi",q:"Sau khi trồng cây con, em cần làm gì?",explain:"Tưới nhẹ, để nơi râm và theo dõi cây; nhổ cây lên làm đứt rễ.",options:["Tưới nhẹ","Để nơi râm vài ngày","Quan sát cây hằng ngày","Nhổ cây lên xem rễ"],answers:[0,1,2]},{id:"cn4-trong-cay-con-15",type:"fill",q:"Khi trồng, cần giữ nguyên bầu … quanh rễ cây con.",emoji:"🟤",answer:["đất"],explain:"Bầu đất giữ cho rễ không bị tổn thương khi trồng."},{id:"cn4-trong-cay-con-16",type:"mc",q:"Cây con bị nghiêng sau khi trồng. Em nên làm gì?",explain:"Dựng cây thẳng lại và ấn nhẹ đất quanh gốc cho cây đứng vững.",options:["Bẻ ngọn cây","Mặc kệ cây","Đổ thêm nhiều nước","Dựng thẳng, ấn đất"],answer:3},{id:"cn4-trong-cay-con-17",type:"tf",q:"Trồng cây con quá sâu, vùi cả lá vào đất là không tốt.",explain:"Đúng. Vùi lá vào đất làm lá thối, cây khó lớn.",answer:!0},{id:"cn4-trong-cay-con-18",type:"mc",q:"Em nên trồng cây con vào thời điểm nào trong ngày?",emoji:"🌇",explain:"Trồng lúc chiều mát giúp cây ít bị mất nước, dễ bén rễ.",options:["Chiều mát","Lúc mưa bão","Nửa đêm","Trưa nắng gắt"],answer:0}]},{questions:[{id:"cn4-trong-cay-con-19",type:"mc",q:"Sau khi trồng, cây con của Chi bị héo vì để ngoài nắng gắt. Chi nên làm gì?",emoji:"🥀",explain:"Chuyển cây vào chỗ râm mát và tưới vừa đủ để cây hồi lại.",options:["Phơi nắng thêm","Chuyển vào chỗ râm","Cắt hết lá","Nhổ cây vứt đi"],answer:1},{id:"cn4-trong-cay-con-20",type:"order",q:"Sắp xếp các việc chuẩn bị trước khi trồng cây con.",items:["Chọn chậu có lỗ thoát nước","Chuẩn bị đất tơi xốp","Chọn cây con khỏe","Đeo găng tay"],explain:"Chuẩn bị chậu, đất, chọn cây khỏe rồi đeo găng tay trước khi trồng."},{id:"cn4-trong-cay-con-21",type:"tf",q:"Trồng xong, Phúc đặt chậu ở chỗ râm và tưới nhẹ. Phúc làm đúng.",emoji:"👍",explain:"Đúng. Cây con mới trồng cần chỗ râm mát và tưới nhẹ để bén rễ.",answer:!0},{id:"cn4-trong-cay-con-22",type:"multi",q:"Những việc nào làm cây con mới trồng dễ chết?",explain:"Đứt rễ, nắng gắt và đất khô làm cây con dễ chết; tưới vừa ẩm là việc làm đúng.",options:["Giật đứt rễ","Để dưới nắng gắt","Tưới nhẹ vừa ẩm","Để đất khô nứt"],answers:[0,1,3]},{id:"cn4-trong-cay-con-23",type:"mc",q:"Vì sao không nên trồng cây con lúc trưa nắng gắt?",emoji:"☀️",explain:"Trưa nắng gắt làm cây con mất nước nhanh, dễ héo.",options:["Cây lớn quá nhanh","Đất bị ướt","Chậu bị nặng","Cây dễ bị héo"],answer:3},{id:"cn4-trong-cay-con-24",type:"match",q:"Nối tình trạng cây với cách xử lí.",explain:"Theo dõi cây con và xử lí kịp thời giúp cây sống khỏe.",pairs:[["Cây bị nghiêng","Dựng thẳng, ấn đất"],["Đất khô","Tưới nhẹ"],["Cây héo vì nắng","Chuyển vào chỗ râm"]]},{id:"cn4-trong-cay-con-25",type:"fill",q:"Cây con mới trồng nên đặt nơi … mát vài ngày.",emoji:"⛱️",answer:["râm"],explain:"Để nơi râm mát giúp cây con kịp bén rễ, không bị héo."},{id:"cn4-trong-cay-con-26",type:"tf",q:"Đất vào mắt khi trồng cây, em nên dụi mắt thật mạnh.",emoji:"⚠️",explain:"Sai. Không dụi mắt; em rửa mắt bằng nước sạch và báo người lớn.",answer:!1}]}],challenge:{questions:[{id:"cn4-trong-cay-con-27",type:"mc",q:"Bình trồng cây con nhưng làm vỡ hết bầu đất, rễ bị đứt. Điều gì dễ xảy ra?",explain:"Rễ bị đứt làm cây khó hút nước, chậm bén rễ và dễ héo.",options:["Cây chậm bén rễ, dễ héo","Cây cao vọt lên","Cây ra hoa ngay","Lá to hơn"],answer:0},{id:"cn4-trong-cay-con-28",type:"multi",q:"Cách nào giúp cây con mới trồng nhanh bén rễ?",explain:"Giữ bầu đất, ấn đất nhẹ và tưới vừa ẩm giúp cây nhanh bén rễ.",options:["Giữ bầu đất","Ấn nhẹ đất quanh gốc","Tưới vừa đủ ẩm","Nhổ lên mỗi ngày"],answers:[0,1,2]},{id:"cn4-trong-cay-con-29",type:"tf",q:"Cây con mới trồng không cần theo dõi, cứ để mặc là lớn.",explain:"Sai. Cần theo dõi, tưới nước và che nắng khi cần trong những ngày đầu.",answer:!1},{id:"cn4-trong-cay-con-02",type:"order",q:"Sắp xếp các bước trồng cây con trong chậu.",items:["Cho đất vào chậu","Tạo hốc ở giữa chậu","Đặt cây con thẳng vào hốc","Lấp đất, ấn nhẹ quanh gốc","Tưới nhẹ quanh gốc"],explain:"Chuẩn bị đất, tạo hốc, đặt cây, lấp đất ấn nhẹ rồi tưới nước."},{id:"cn4-trong-cay-con-22",type:"multi",q:"Những việc nào làm cây con mới trồng dễ chết?",explain:"Đứt rễ, nắng gắt và đất khô làm cây con dễ chết; tưới vừa ẩm là việc làm đúng.",options:["Giật đứt rễ","Để dưới nắng gắt","Tưới nhẹ vừa ẩm","Để đất khô nứt"],answers:[0,1,3]},{id:"cn4-trong-cay-con-24",type:"match",q:"Nối tình trạng cây với cách xử lí.",explain:"Theo dõi cây con và xử lí kịp thời giúp cây sống khỏe.",pairs:[["Cây bị nghiêng","Dựng thẳng, ấn đất"],["Đất khô","Tưới nhẹ"],["Cây héo vì nắng","Chuyển vào chỗ râm"]]},{id:"cn4-trong-cay-con-12",type:"tf",q:"Lấy cây con ra khỏi bầu, nên cầm thật chặt ngọn cây rồi giật mạnh.",explain:"Sai. Giật mạnh làm gãy cây, đứt rễ; cần nhẹ nhàng lấy cả bầu đất.",answer:!1}]},summary:["Chọn cây con khỏe và giữ nguyên bầu đất khi trồng.","Đặt cây thẳng, lấp đất, ấn nhẹ quanh gốc rồi tưới nhẹ.","Cây mới trồng cần để nơi râm mát vài ngày cho bén rễ."]},{id:"cn4-cham-soc",title:"Chăm sóc hoa và cây cảnh trong chậu",weeks:[15,17],learn:[{title:"Tưới nước",text:"Tưới khi đất mặt chậu khô, vào sáng sớm hoặc chiều mát. Tưới vừa đủ, không để đất úng nước.",example:"👆 đất khô → 🚿 tưới vừa đủ"},{title:"Nhổ cỏ, xới đất, bón phân",text:"Nhổ cỏ dại, xới nhẹ đất quanh gốc. Bón phân đúng loại, đúng lượng và làm cùng người lớn.",example:"🌿 nhổ cỏ · 🍴 xới đất · ⚖️ bón đúng lượng"},{title:"Ánh sáng và sâu bệnh",text:"Đặt cây nơi đủ ánh sáng phù hợp, tỉa lá úa. Thấy sâu bệnh thì báo người lớn, không tự dùng thuốc.",example:"☀️ đủ sáng · 🍂 tỉa lá úa · 🐛 báo người lớn"}],practice:[{questions:[{id:"cn4-cham-soc-01",type:"mc",q:"Nên tưới cây vào lúc nào trong ngày?",emoji:"🌅",explain:"Tưới lúc sáng sớm hoặc chiều mát giúp cây hút nước tốt, ít bay hơi.",options:["Sáng sớm, chiều mát","Lúc mưa to","Nửa đêm","Trưa nắng gắt"],answer:0},{id:"cn4-cham-soc-02",type:"tf",q:"Nhổ cỏ dại trong chậu giúp cây không bị tranh chất dinh dưỡng.",emoji:"🌿",explain:"Đúng. Cỏ dại tranh nước và chất dinh dưỡng với cây trồng.",answer:!0},{id:"cn4-cham-soc-03",type:"mc",q:"Lá vàng úa, cành khô trên cây nên làm gì?",emoji:"🍂",explain:"Tỉa bỏ lá úa, cành khô giúp cây thoáng và đẹp hơn.",options:["Sơn xanh lại","Tỉa bỏ","Dán lại cho chắc","Tưới thêm cho lá"],answer:1},{id:"cn4-cham-soc-04",type:"match",q:"Nối việc chăm sóc với tác dụng.",explain:"Mỗi việc chăm sóc giúp cây lớn khỏe theo một cách.",pairs:[["Tưới nước","Cây đủ nước"],["Nhổ cỏ","Bớt tranh dinh dưỡng"],["Xới đất","Đất tơi, thoáng"]]},{id:"cn4-cham-soc-05",type:"fill",q:"Cỏ mọc lẫn trong chậu hoa cần được … bỏ.",emoji:"🌿",answer:["nhổ"],explain:"Nhổ cỏ dại giúp cây hoa không bị tranh nước và chất dinh dưỡng."},{id:"cn4-cham-soc-06",type:"multi",q:"Những việc nào là chăm sóc cây trong chậu?",explain:"Tưới nước, nhổ cỏ, bón phân là chăm sóc cây; bẻ ngọn làm hại cây.",options:["Tưới nước","Nhổ cỏ","Bón phân","Bẻ ngọn cho vui"],answers:[0,1,2]},{id:"cn4-cham-soc-07",type:"tf",q:"Bón càng nhiều phân thì cây càng tốt.",emoji:"⚠️",explain:"Sai. Bón quá nhiều phân có thể làm cây bị hại; cần bón đúng lượng.",answer:!1},{id:"cn4-cham-soc-08",type:"mc",q:"Cây trong chậu cần đặt ở chỗ thế nào?",emoji:"☀️",explain:"Cây cần ánh sáng để sống; mỗi loại cần lượng ánh sáng khác nhau.",options:["Đủ ánh sáng phù hợp","Tối om cả ngày","Trong tủ lạnh","Sát bếp lửa"],answer:0},{id:"cn4-cham-soc-09",type:"tf",q:"Khi bón phân cho cây, em nên làm cùng người lớn.",emoji:"🧑‍🌾",explain:"Đúng. Người lớn giúp em bón đúng loại, đúng lượng và an toàn.",answer:!0}]},{questions:[{id:"cn4-cham-soc-10",type:"mc",q:"Làm sao biết chậu cây cần tưới?",emoji:"👆",explain:"Khi đất mặt chậu khô là lúc cần tưới thêm nước cho cây.",options:["Lá đang rất tươi","Đất đang sũng nước","Trời đang mưa to","Đất mặt chậu khô"],answer:3},{id:"cn4-cham-soc-11",type:"tf",q:"Tưới quá nhiều nước làm đất úng, rễ cây dễ bị thối.",emoji:"💧",explain:"Đúng. Rễ cây cần không khí; đất úng lâu làm rễ thối, lá vàng.",answer:!0},{id:"cn4-cham-soc-12",type:"mc",q:"Vì sao không nên tưới cây lúc trưa nắng gắt?",explain:"Buổi trưa nắng gắt nước bay hơi nhanh, cây khó hút đủ nước.",options:["Nước bị đông đá","Cây sẽ ngủ","Nước bay hơi nhanh","Đất bị lạnh"],answer:2},{id:"cn4-cham-soc-13",type:"order",q:"Sắp xếp các việc chăm sóc chậu hoa.",items:["Nhổ cỏ dại","Xới nhẹ đất quanh gốc","Bón phân với người lớn","Tưới nước"],explain:"Nhổ cỏ, xới đất, bón phân rồi tưới để phân tan vào đất."},{id:"cn4-cham-soc-14",type:"mc",q:"Xới đất quanh gốc cây cần làm thế nào?",explain:"Xới nhẹ giúp đất tơi mà không làm đứt rễ cây.",options:["Đào sâu sát rễ","Xới nhẹ, không chạm rễ","Đập đất thật mạnh","Nhổ cây lên rồi xới"],answer:1},{id:"cn4-cham-soc-15",type:"multi",q:"Dấu hiệu nào cho thấy cây có thể bị tưới quá nhiều nước?",explain:"Đất sũng, nước đọng, lá vàng và rễ thối là dấu hiệu tưới quá nhiều.",options:["Đất luôn sũng nước","Lá vàng, rễ thối","Lá xanh tươi","Có nước đọng ở đáy"],answers:[0,1,3]},{id:"cn4-cham-soc-16",type:"fill",q:"Bón phân cho cây cần đúng loại và đúng … .",emoji:"⚖️",answer:["lượng","liều lượng"],explain:"Bón đúng lượng giúp cây khỏe; bón quá nhiều có thể hại cây."},{id:"cn4-cham-soc-17",type:"tf",q:"Thấy sâu trên lá, em nên tự lấy thuốc trừ sâu của bố mẹ để phun.",emoji:"🐛",explain:"Sai. Thuốc trừ sâu độc hại; em báo người lớn để xử lí an toàn.",answer:!1},{id:"cn4-cham-soc-18",type:"mc",q:"Cây hoa trong nhà mọc vươn dài, lá nhợt nhạt. Có thể cây thiếu gì?",explain:"Thiếu ánh sáng làm cây vươn dài, lá nhạt màu; nên đặt nơi sáng hơn.",options:["Thừa ánh sáng","Thiếu ánh sáng","Thừa gió","Chậu quá đẹp"],answer:1}]},{questions:[{id:"cn4-cham-soc-19",type:"mc",q:"Chậu hoa của Nam đất khô nứt, lá héo rũ. Nam nên làm gì trước tiên?",emoji:"🥀",explain:"Đất khô, lá héo là cây thiếu nước; Nam cần tưới nước cho cây.",options:["Tưới nước","Bón thật nhiều phân","Tỉa hết lá","Cất vào tủ"],answer:0},{id:"cn4-cham-soc-20",type:"mc",q:"Vy thấy có sâu đang ăn lá hoa hồng. Vy nên làm gì?",emoji:"🐛",explain:"Vy báo người lớn để bắt sâu hoặc xử lí an toàn, không tự dùng thuốc.",options:["Tự phun thuốc","Báo người lớn","Ăn thử lá","Bỏ mặc cây"],answer:1},{id:"cn4-cham-soc-21",type:"match",q:"Nối dấu hiệu của cây với cách chăm sóc.",explain:"Quan sát cây giúp em chọn cách chăm sóc đúng.",pairs:[["Đất khô, lá héo","Tưới nước"],["Có nhiều cỏ dại","Nhổ cỏ"],["Lá vàng úa","Tỉa bỏ lá úa"]]},{id:"cn4-cham-soc-22",type:"tf",q:"Cả nhà đi xa một tuần, nhờ hàng xóm tưới giúp cây là cách hay.",emoji:"🤝",explain:"Đúng. Nhờ người tưới giúp giữ cho cây không bị khô héo khi cả nhà vắng nhà.",answer:!0},{id:"cn4-cham-soc-23",type:"multi",q:"Khoa bón phân cho chậu cúc. Việc nào đúng?",explain:"Bón phân cùng người lớn, đúng lượng và rửa tay sau đó; tuyệt đối không cho phân vào miệng.",options:["Làm cùng người lớn","Bón đúng lượng","Rửa tay sau khi bón","Nếm thử phân bón"],answers:[0,1,2]},{id:"cn4-cham-soc-24",type:"mc",q:"Cây trầu bà để trong góc tối lâu ngày, lá nhạt màu. Em nên làm gì?",explain:"Lá nhạt màu do thiếu sáng; chuyển cây đến nơi có ánh sáng nhẹ.",options:["Cắt hết rễ","Tưới gấp đôi nước","Bón thật nhiều phân","Đặt nơi sáng hơn"],answer:3},{id:"cn4-cham-soc-25",type:"fill",q:"Tưới cây nên vào buổi sáng sớm hoặc chiều … .",emoji:"🌇",answer:["mát"],explain:"Sáng sớm, chiều mát nắng dịu, nước ít bay hơi, cây hút nước tốt."},{id:"cn4-cham-soc-26",type:"tf",q:"Sau khi chăm sóc cây, nhổ cỏ, bón phân, em cần rửa tay bằng xà phòng.",emoji:"🧼",explain:"Đúng. Tay dính đất, phân bón cần rửa sạch để phòng bệnh.",answer:!0}]}],challenge:{questions:[{id:"cn4-cham-soc-27",type:"order",q:"Sắp xếp cách Hà kiểm tra và tưới chậu hoa.",items:["Sờ thử đất mặt chậu","Thấy đất khô thì tưới","Tưới nhẹ quanh gốc","Xem nước thừa thoát ra ở đáy"],explain:"Kiểm tra đất trước, đất khô mới tưới, tưới nhẹ và xem nước thừa thoát ra."},{id:"cn4-cham-soc-28",type:"multi",q:"Chọn những cách chăm sóc cây đúng.",explain:"Tưới vừa đủ, đủ ánh sáng, tỉa lá úa là đúng; bón quá nhiều phân có thể hại cây.",options:["Tưới vừa đủ","Đặt nơi đủ sáng","Tỉa lá úa","Bón phân thật nhiều"],answers:[0,1,2]},{id:"cn4-cham-soc-29",type:"mc",q:"Lá cây vàng, đất sũng nước, đáy chậu đọng nước. Nguyên nhân có thể là gì?",explain:"Đất sũng nước, đáy đọng nước cho thấy cây bị tưới quá nhiều, rễ bị úng.",options:["Tưới quá nhiều","Thiếu cỏ dại","Chậu quá nhẹ","Thiếu nước"],answer:0},{id:"cn4-cham-soc-20",type:"mc",q:"Vy thấy có sâu đang ăn lá hoa hồng. Vy nên làm gì?",emoji:"🐛",explain:"Vy báo người lớn để bắt sâu hoặc xử lí an toàn, không tự dùng thuốc.",options:["Tự phun thuốc","Báo người lớn","Ăn thử lá","Bỏ mặc cây"],answer:1},{id:"cn4-cham-soc-23",type:"multi",q:"Khoa bón phân cho chậu cúc. Việc nào đúng?",explain:"Bón phân cùng người lớn, đúng lượng và rửa tay sau đó; tuyệt đối không cho phân vào miệng.",options:["Làm cùng người lớn","Bón đúng lượng","Rửa tay sau khi bón","Nếm thử phân bón"],answers:[0,1,2]},{id:"cn4-cham-soc-15",type:"multi",q:"Dấu hiệu nào cho thấy cây có thể bị tưới quá nhiều nước?",explain:"Đất sũng, nước đọng, lá vàng và rễ thối là dấu hiệu tưới quá nhiều.",options:["Đất luôn sũng nước","Lá vàng, rễ thối","Lá xanh tươi","Có nước đọng ở đáy"],answers:[0,1,3]},{id:"cn4-cham-soc-17",type:"tf",q:"Thấy sâu trên lá, em nên tự lấy thuốc trừ sâu của bố mẹ để phun.",emoji:"🐛",explain:"Sai. Thuốc trừ sâu độc hại; em báo người lớn để xử lí an toàn.",answer:!1}]},summary:["Tưới vừa đủ khi đất khô, vào sáng sớm hoặc chiều mát.","Nhổ cỏ, xới đất, tỉa lá úa và bón phân đúng lượng cùng người lớn.","Thấy sâu bệnh thì báo người lớn; rửa tay sạch sau khi chăm sóc cây."]}]},{id:"lap-ghep-mo-hinh",title:"Lắp ghép mô hình kĩ thuật",lessons:[{id:"cn4-bo-lap-ghep",title:"Bộ lắp ghép mô hình kĩ thuật",weeks:[18,19],learn:[{title:"Bộ lắp ghép là gì?",text:"Bộ lắp ghép gồm nhiều chi tiết bằng nhựa hoặc kim loại. Em ghép chúng lại để làm mô hình như xe, cái đu, rô-bốt.",example:"🧩 chi tiết + 🔩 ốc vít ➜ 🚗 mô hình"},{title:"Các nhóm chi tiết",text:"Bộ lắp ghép có chi tiết dạng tấm, thanh thẳng có lỗ, thanh chữ U, thanh chữ L, bánh xe, trục, ốc và vít.",example:"▭ tấm · ━ thanh · ⚙️ bánh xe · 🔩 ốc vít"},{title:"Dụng cụ đi kèm",text:"Tua-vít dùng để vặn vít, cờ-lê dùng để giữ và vặn đai ốc. Dùng xong, em xếp gọn chi tiết vào hộp.",example:"🪛 tua-vít · 🔧 cờ-lê · 📦 hộp đựng"}],practice:[{questions:[{id:"cn4-bo-lap-ghep-01",type:"mc",q:"Dụng cụ nào dùng để vặn vít?",emoji:"🪛",explain:"Tua-vít có đầu vừa với rãnh vít, dùng để vặn vít.",options:["Cờ-lê","Thước kẻ","Kéo","Tua-vít"],answer:3},{id:"cn4-bo-lap-ghep-02",type:"mc",q:"Cờ-lê dùng để làm gì?",emoji:"🔧",explain:"Cờ-lê kẹp vào đai ốc để giữ hoặc vặn đai ốc.",options:["Cắt bìa cứng","Giữ, vặn đai ốc","Đo chiều dài","Dán chi tiết"],answer:1},{id:"cn4-bo-lap-ghep-03",type:"tf",q:"Bánh xe là một chi tiết trong bộ lắp ghép.",emoji:"⚙️",explain:"Đúng. Bánh xe giúp mô hình như ô tô, xe đẩy lăn được.",answer:!0},{id:"cn4-bo-lap-ghep-04",type:"tf",q:"Bộ lắp ghép chỉ có các chi tiết dạng tấm.",explain:"Sai. Bộ lắp ghép có tấm, thanh thẳng, thanh chữ U, chữ L, bánh xe, trục, ốc và vít.",answer:!1},{id:"cn4-bo-lap-ghep-05",type:"match",q:"Nối dụng cụ với công dụng của nó.",explain:"Tua-vít vặn vít, cờ-lê giữ và vặn đai ốc, hộp để cất chi tiết.",pairs:[["Tua-vít","Vặn vít"],["Cờ-lê","Giữ, vặn đai ốc"],["Hộp đựng","Cất gọn chi tiết"]]},{id:"cn4-bo-lap-ghep-06",type:"multi",q:"Đâu là chi tiết của bộ lắp ghép?",explain:"Bút chì là đồ dùng học tập, không phải chi tiết của bộ lắp ghép.",options:["Bánh xe","Thanh thẳng có lỗ","Ốc và vít","Bút chì"],answers:[0,1,2]},{id:"cn4-bo-lap-ghep-07",type:"fill",q:"Dụng cụ dùng để vặn vít gọi là … .",explain:"Tua-vít là dụng cụ dùng để vặn vít.",answer:["tua-vít","tua vít","tuốc-nơ-vít","tuốc nơ vít"]},{id:"cn4-bo-lap-ghep-08",type:"mc",q:"Chi tiết nào giúp mô hình xe lăn được?",emoji:"🚗",explain:"Bánh xe lắp vào trục giúp mô hình xe lăn được.",options:["Tấm nhỏ","Đai ốc","Thanh chữ L","Bánh xe"],answer:3},{id:"cn4-bo-lap-ghep-09",type:"mc",q:"Ốc và vít dùng để làm gì?",emoji:"🔩",explain:"Ốc và vít giữ các chi tiết nối chặt với nhau.",options:["Trang trí mô hình","Nối chặt chi tiết","Làm mô hình nhẹ","Thay cho bánh xe"],answer:1}]},{questions:[{id:"cn4-bo-lap-ghep-10",type:"mc",q:"Vì sao các thanh thẳng có nhiều lỗ?",explain:"Các lỗ để luồn vít, ghép thanh với chi tiết khác ở nhiều vị trí.",options:["Để mô hình đẹp hơn","Để luồn vít ghép nối","Để thanh nhẹ hơn","Để buộc dây treo"],answer:1},{id:"cn4-bo-lap-ghep-11",type:"tf",q:"Dùng xong bộ lắp ghép, em nên xếp các chi tiết gọn vào hộp.",emoji:"📦",explain:"Đúng. Xếp gọn vào hộp giúp không mất chi tiết, lần sau dễ tìm.",answer:!0},{id:"cn4-bo-lap-ghep-12",type:"tf",q:"Có thể dùng kéo thay tua-vít để vặn vít cho nhanh.",explain:"Sai. Dùng kéo dễ đứt tay và làm hỏng vít; em dùng đúng tua-vít.",answer:!1},{id:"cn4-bo-lap-ghep-13",type:"match",q:"Nối chi tiết với việc nó làm trong mô hình xe.",explain:"Mỗi chi tiết có một việc riêng khi ghép thành mô hình xe.",pairs:[["Bánh xe","Giúp xe lăn"],["Trục","Xuyên qua bánh xe"],["Tấm lớn","Làm sàn xe"],["Ốc vít","Giữ chặt chi tiết"]]},{id:"cn4-bo-lap-ghep-14",type:"order",q:"Sắp xếp các bước làm quen với bộ lắp ghép.",explain:"Quan sát, gọi tên, thử ghép rồi cất gọn vào hộp.",items:["Mở hộp, quan sát chi tiết","Gọi tên từng nhóm chi tiết","Thử ghép hai chi tiết","Xếp gọn chi tiết vào hộp"]},{id:"cn4-bo-lap-ghep-15",type:"multi",q:"Việc nào giúp em không làm mất chi tiết?",explain:"Vứt bừa trên sàn dễ làm rơi, mất chi tiết nhỏ.",options:["Để chi tiết trên khay","Đếm lại trước khi cất","Vứt bừa trên sàn","Cất theo ngăn trong hộp"],answers:[0,1,3]},{id:"cn4-bo-lap-ghep-16",type:"mc",q:"Thanh chữ L có hình dạng thế nào?",explain:"Thanh chữ L gập thành một góc vuông giống chữ L.",options:["Thẳng một đường","Gập thành góc vuông","Tròn như bánh xe","Phẳng như tấm"],answer:1},{id:"cn4-bo-lap-ghep-17",type:"fill",q:"Chi tiết nhỏ vặn vào vít để giữ chặt gọi là đai … .",explain:"Đai ốc vặn vào vít ở phía bên kia để giữ chặt chi tiết.",answer:["ốc"]},{id:"cn4-bo-lap-ghep-18",type:"mc",q:"Đâu KHÔNG phải là chi tiết của bộ lắp ghép?",explain:"Cục tẩy là đồ dùng học tập, không dùng để lắp ghép mô hình.",options:["Cục tẩy","Trục","Bánh xe","Thanh chữ U"],answer:0}]},{questions:[{id:"cn4-bo-lap-ghep-19",type:"mc",q:"Nam muốn lắp mô hình xe chạy được. Nam cần thêm gì?",emoji:"🚙",explain:"Xe muốn lăn được phải có bánh xe lắp vào trục.",options:["Tấm lớn thôi","Bánh xe, trục","Vài con ốc","Thanh chữ U"],answer:1},{id:"cn4-bo-lap-ghep-20",type:"tf",q:"Khi một con vít bị lỏng, em nên vặn chặt lại bằng tua-vít.",explain:"Đúng. Vặn chặt vít giúp mô hình chắc chắn, không rời ra.",answer:!0},{id:"cn4-bo-lap-ghep-21",type:"mc",q:"Lan làm rơi một con ốc xuống gầm bàn. Lan nên làm gì?",explain:"Nhặt ốc cất vào hộp để không mất và không ai giẫm phải.",options:["Bỏ qua, lắp tiếp","Đá đi chỗ khác","Cho vào miệng giữ","Nhặt lên, cất vào hộp"],answer:3},{id:"cn4-bo-lap-ghep-22",type:"multi",q:"Bạn nào dùng bộ lắp ghép đúng cách?",explain:"Ngậm ốc vít có thể nuốt phải, ném chi tiết dễ làm bạn đau.",options:["Hà xếp chi tiết theo nhóm","Tùng ngậm ốc vít trong miệng","Chi cất gọn sau khi chơi","Minh ném chi tiết vào bạn"],answers:[0,2]},{id:"cn4-bo-lap-ghep-23",type:"match",q:"Nối tình huống với cách làm đúng.",explain:"Mỗi tình huống có một cách xử lí gọn gàng, an toàn.",pairs:[["Vít bị lỏng","Vặn chặt lại"],["Thiếu một chi tiết","Tìm trong hộp"],["Chơi xong","Xếp gọn vào hộp"]]},{id:"cn4-bo-lap-ghep-24",type:"order",q:"Sắp xếp các bước cất bộ lắp ghép sau khi chơi.",explain:"Tháo rời, phân loại, kiểm tra đủ rồi mới cất vào hộp.",items:["Tháo rời các chi tiết","Phân loại theo nhóm","Kiểm tra đủ chi tiết","Xếp vào hộp, đậy nắp"]},{id:"cn4-bo-lap-ghep-25",type:"tf",q:"Em bé hai tuổi có thể chơi ốc vít nhỏ một mình.",emoji:"👶",explain:"Sai. Em bé có thể nuốt phải ốc vít nhỏ, rất nguy hiểm.",answer:!1},{id:"cn4-bo-lap-ghep-26",type:"fill",q:"Khi chơi xong, em xếp các chi tiết gọn gàng vào … .",explain:"Cất chi tiết vào hộp giúp không bị mất.",answer:["hộp","hộp đựng"]}]}],challenge:{questions:[{id:"cn4-bo-lap-ghep-27",type:"mc",q:"Chi tiết nào thường làm sàn của mô hình xe?",explain:"Tấm lớn phẳng, rộng nên hay dùng làm sàn xe.",options:["Tấm lớn","Con ốc","Tua-vít","Cờ-lê"],answer:0},{id:"cn4-bo-lap-ghep-28",type:"multi",q:"Đâu là dụng cụ, không phải chi tiết của mô hình?",explain:"Tua-vít và cờ-lê dùng để lắp, không nằm trong mô hình.",options:["Tua-vít","Cờ-lê","Bánh xe","Thanh chữ U"],answers:[0,1]},{id:"cn4-bo-lap-ghep-29",type:"tf",q:"Mô hình lắp ghép có nhiều vít lỏng thì càng chắc chắn.",explain:"Sai. Vít lỏng làm chi tiết lung lay, dễ rời ra.",answer:!1},{id:"cn4-bo-lap-ghep-30",type:"mc",q:"Ngọc vặn vít mãi không chặt. Có thể vì sao?",explain:"Vít cần đai ốc ở phía bên kia giữ lại thì mới chặt được.",options:["Bánh xe quá to","Chưa có đai ốc giữ","Hộp đựng bị mở","Vít quá sạch"],answer:1},{id:"cn4-bo-lap-ghep-31",type:"match",q:"Nối chi tiết với hình dạng của nó.",explain:"Tên của thanh chữ U, chữ L gợi ra hình dạng của nó.",pairs:[["Thanh chữ U","Gập ở hai đầu"],["Thanh chữ L","Gập một góc"],["Thanh thẳng","Thẳng, có lỗ"],["Bánh xe","Hình tròn"]]},{id:"cn4-bo-lap-ghep-32",type:"order",q:"Sắp xếp các bước ghép hai thanh bằng ốc vít.",explain:"Đặt trùng lỗ, luồn vít, vặn đai ốc rồi vặn chặt.",items:["Đặt hai lỗ trùng nhau","Luồn vít qua hai lỗ","Vặn đai ốc vào vít","Vặn chặt bằng dụng cụ"]},{id:"cn4-bo-lap-ghep-33",type:"fill",q:"Để ghép hai thanh, em luồn … qua hai lỗ trùng nhau.",explain:"Vít luồn qua hai lỗ trùng nhau rồi vặn đai ốc giữ lại.",answer:["vít","con vít"]}]},summary:["Bộ lắp ghép có tấm, thanh thẳng, thanh chữ U, chữ L, bánh xe, trục, ốc và vít.","Tua-vít dùng để vặn vít, cờ-lê dùng để giữ và vặn đai ốc.","Chơi xong, em xếp gọn chi tiết vào hộp, không để em nhỏ ngậm ốc vít."]},{id:"cn4-thao-lap",title:"Lắp và tháo các chi tiết",weeks:[20,21],learn:[{title:"Lắp ghép bằng ốc vít",text:"Đặt hai lỗ của chi tiết trùng nhau, luồn vít qua lỗ rồi vặn đai ốc ở phía bên kia.",example:"━ + ━ ➜ 🔩 ➜ 🔧"},{title:"Vặn chặt, vặn lỏng",text:"Vặn tua-vít cùng chiều kim đồng hồ để vít chặt, vặn ngược chiều kim đồng hồ để tháo vít.",example:"🕐 cùng chiều: chặt · ngược chiều: lỏng"},{title:"Tháo mô hình",text:"Tháo theo thứ tự ngược với khi lắp: bộ phận lắp sau thì tháo trước. Tháo xong, xếp chi tiết vào hộp.",example:"lắp 1 ➜ 2 ➜ 3 · tháo 3 ➜ 2 ➜ 1"}],practice:[{questions:[{id:"cn4-thao-lap-01",type:"mc",q:"Để vít chặt hơn, em vặn tua-vít theo chiều nào?",emoji:"🕐",explain:"Vặn cùng chiều kim đồng hồ thì vít chặt dần.",options:["Lắc qua lắc lại","Ngược chiều kim đồng hồ","Cùng chiều kim đồng hồ"],answer:2},{id:"cn4-thao-lap-02",type:"tf",q:"Khi tháo mô hình, em tháo theo thứ tự ngược với khi lắp.",explain:"Đúng. Bộ phận lắp sau thì tháo trước.",answer:!0},{id:"cn4-thao-lap-03",type:"fill",q:"Vặn tua-vít ngược chiều kim đồng hồ thì vít sẽ … ra.",explain:"Vặn ngược chiều kim đồng hồ làm vít lỏng ra để tháo.",answer:["lỏng"]},{id:"cn4-thao-lap-04",type:"mc",q:"Trước khi luồn vít, em cần làm gì với hai lỗ?",explain:"Hai lỗ trùng nhau thì vít mới luồn qua được.",options:["Đặt trùng hai lỗ","Dán băng dính lên","Bẻ cong chi tiết","Tô màu hai lỗ"],answer:0},{id:"cn4-thao-lap-05",type:"match",q:"Nối dụng cụ với việc làm khi lắp ghép.",explain:"Dùng đúng dụng cụ giúp lắp nhanh và an toàn.",pairs:[["Tua-vít","Vặn vít"],["Cờ-lê","Giữ đai ốc"],["Khay nhựa","Đựng chi tiết nhỏ"]]},{id:"cn4-thao-lap-06",type:"tf",q:"Đai ốc được vặn vào vít ở phía bên kia của chi tiết.",explain:"Đúng. Vít luồn qua lỗ, đai ốc vặn vào đầu vít ở phía bên kia.",answer:!0},{id:"cn4-thao-lap-07",type:"tf",q:"Vặn vít càng mạnh tay càng tốt, kể cả khi vít đã chặt.",explain:"Sai. Vít đã chặt mà vẫn cố vặn sẽ làm hỏng ren vít.",answer:!1},{id:"cn4-thao-lap-08",type:"multi",q:"Khi lắp ghép, em cần chuẩn bị gì?",explain:"Chuẩn bị chi tiết, dụng cụ và chỗ ngồi gọn gàng; không vừa ăn vừa lắp.",options:["Chi tiết cần dùng","Tua-vít và cờ-lê","Chỗ ngồi gọn gàng","Kẹo để ăn"],answers:[0,1,2]},{id:"cn4-thao-lap-09",type:"mc",q:"Bộ phận lắp sau cùng thì khi tháo sẽ tháo lúc nào?",explain:"Tháo ngược với khi lắp: lắp sau cùng thì tháo đầu tiên.",options:["Không cần tháo","Tháo cuối cùng","Tháo đầu tiên"],answer:2}]},{questions:[{id:"cn4-thao-lap-10",type:"order",q:"Sắp xếp các bước ghép hai chi tiết bằng ốc vít.",explain:"Chọn chi tiết, đặt trùng lỗ, luồn vít rồi vặn đai ốc.",items:["Chọn đúng chi tiết cần ghép","Đặt các lỗ trùng nhau","Luồn vít qua lỗ","Vặn đai ốc, siết chặt"]},{id:"cn4-thao-lap-11",type:"mc",q:"Vì sao nên tháo theo thứ tự ngược với khi lắp?",explain:"Tháo ngược thứ tự giúp chi tiết không bị kẹt, gãy hay cong.",options:["Để chi tiết không hỏng","Để tháo nhanh như chớp","Để chi tiết đổi màu"],answer:0},{id:"cn4-thao-lap-12",type:"tf",q:"Nếu vít bị kẹt cứng, em có thể nhờ người lớn giúp.",explain:"Đúng. Người lớn giúp em tháo vít kẹt mà không làm hỏng chi tiết.",answer:!0},{id:"cn4-thao-lap-13",type:"mc",q:"Minh vặn vít ngược chiều kim đồng hồ. Vít sẽ thế nào?",explain:"Vặn ngược chiều kim đồng hồ thì vít lỏng dần ra.",options:["Chặt hơn","Lỏng dần ra","Đứng yên mãi","Gãy đôi ngay"],answer:1},{id:"cn4-thao-lap-14",type:"match",q:"Nối việc làm với kết quả.",explain:"Chiều vặn quyết định vít chặt hay lỏng.",pairs:[["Vặn cùng chiều kim đồng hồ","Vít chặt hơn"],["Vặn ngược chiều kim đồng hồ","Vít lỏng ra"],["Tháo xong cất vào hộp","Không mất chi tiết"]]},{id:"cn4-thao-lap-15",type:"multi",q:"Việc nào giúp mô hình lắp chắc chắn?",explain:"Bỏ bớt đai ốc làm vít không được giữ chặt.",options:["Vặn chặt mọi con vít","Chọn đúng chi tiết","Bỏ bớt đai ốc","Kiểm tra sau khi lắp"],answers:[0,1,3]},{id:"cn4-thao-lap-16",type:"fill",q:"Bộ phận lắp sau thì khi tháo sẽ được tháo … .",explain:"Tháo theo thứ tự ngược với khi lắp.",answer:["trước"]},{id:"cn4-thao-lap-17",type:"tf",q:"Tháo mô hình xong, em để các chi tiết rơi vãi khắp sàn.",explain:"Sai. Em xếp chi tiết vào hộp để không mất và không ai giẫm phải.",answer:!1},{id:"cn4-thao-lap-18",type:"mc",q:"Khi lắp, nên để các chi tiết nhỏ ở đâu?",explain:"Để chi tiết nhỏ trong khay giúp dễ lấy, không bị rơi mất.",options:["Trong túi áo","Trên mép bàn","Trong khay","Dưới gầm ghế"],answer:2}]},{questions:[{id:"cn4-thao-lap-19",type:"mc",q:"Vy lắp xong thấy bánh xe lắc lư. Vy nên làm gì?",explain:"Bánh xe lắc lư thường do vít ở trục còn lỏng.",options:["Bỏ bánh xe đi","Vặn chặt vít ở trục","Dán băng dính","Mặc kệ, chơi tiếp"],answer:1},{id:"cn4-thao-lap-20",type:"order",q:"Sắp xếp các bước tháo một mô hình.",explain:"Tháo từ bộ phận lắp sau cùng, tháo rời rồi xếp vào hộp.",items:["Tháo bộ phận lắp sau cùng","Tháo dần các bộ phận còn lại","Tháo rời từng chi tiết","Xếp chi tiết vào hộp"]},{id:"cn4-thao-lap-21",type:"tf",q:"Thấy vít khó luồn, em nên kiểm tra lại hai lỗ đã trùng nhau chưa.",explain:"Đúng. Hai lỗ lệch nhau thì vít không luồn qua được.",answer:!0},{id:"cn4-thao-lap-22",type:"multi",q:"Bình tháo mô hình rô-bốt. Bình làm đúng việc nào?",explain:"Giật mạnh dễ làm gãy, cong chi tiết.",options:["Tháo phần lắp sau cùng trước","Giật mạnh cho nhanh","Vặn ngược chiều để tháo vít","Cất ốc vít vào hộp"],answers:[0,2,3]},{id:"cn4-thao-lap-23",type:"match",q:"Nối tình huống với cách xử lí.",explain:"Bình tĩnh tìm cách sửa, cần thì nhờ người lớn.",pairs:[["Vít bị kẹt cứng","Nhờ người lớn giúp"],["Hai lỗ lệch nhau","Chỉnh cho trùng lỗ"],["Thiếu đai ốc","Tìm trong hộp đựng"]]},{id:"cn4-thao-lap-24",type:"mc",q:"Thảo dùng cờ-lê và tua-vít cùng lúc để làm gì?",explain:"Cờ-lê giữ đai ốc đứng yên, tua-vít vặn vít cho chặt.",options:["Gõ vào chi tiết","Cắt thanh thẳng","Đo chiều dài","Giữ đai ốc, vặn vít"],answer:3},{id:"cn4-thao-lap-25",type:"tf",q:"Khi tháo, em có thể tháo bất kì chi tiết nào trước cũng được.",explain:"Sai. Em tháo theo thứ tự ngược với khi lắp để không hỏng chi tiết.",answer:!1},{id:"cn4-thao-lap-26",type:"fill",q:"Vặn vít cùng chiều kim đồng hồ thì vít sẽ … hơn.",explain:"Cùng chiều kim đồng hồ là chiều vặn chặt.",answer:["chặt"]}]}],challenge:{questions:[{id:"cn4-thao-lap-20",type:"order",q:"Sắp xếp các bước tháo một mô hình.",explain:"Tháo từ bộ phận lắp sau cùng, tháo rời rồi xếp vào hộp.",items:["Tháo bộ phận lắp sau cùng","Tháo dần các bộ phận còn lại","Tháo rời từng chi tiết","Xếp chi tiết vào hộp"]},{id:"cn4-thao-lap-27",type:"mc",q:"Tùng lắc nhẹ mô hình thấy chi tiết rời ra. Vì sao?",explain:"Vít chưa vặn chặt thì chi tiết dễ rời ra.",options:["Chi tiết quá mới","Vít chưa vặn chặt","Bàn quá phẳng","Hộp màu đỏ"],answer:1},{id:"cn4-thao-lap-28",type:"tf",q:"Kiểm tra độ chắc chắn sau khi lắp là việc cần làm.",explain:"Đúng. Kiểm tra giúp em phát hiện vít lỏng, chi tiết lệch để sửa.",answer:!0},{id:"cn4-thao-lap-29",type:"multi",q:"Đâu là cách làm vít lỏng ra để tháo?",explain:"Vặn ngược chiều kim đồng hồ thì vít lỏng ra.",options:["Vặn ngược chiều kim đồng hồ","Vặn cùng chiều kim đồng hồ"],answers:[0]},{id:"cn4-thao-lap-30",type:"match",q:"Nối bước với việc làm khi lắp hai chi tiết.",explain:"Đặt trùng lỗ, luồn vít, rồi vặn đai ốc.",pairs:[["Bước 1","Đặt trùng lỗ"],["Bước 2","Luồn vít qua lỗ"],["Bước 3","Vặn đai ốc vào"]]},{id:"cn4-thao-lap-31",type:"mc",q:"Lắp theo thứ tự A, B, C thì tháo theo thứ tự nào?",explain:"Tháo ngược với khi lắp: C trước, rồi B, cuối cùng là A.",options:["A, B, C","B, A, C","C, B, A","A, C, B"],answer:2},{id:"cn4-thao-lap-32",type:"fill",q:"Khi tháo mô hình, em làm theo thứ tự … với khi lắp.",explain:"Bộ phận lắp sau thì tháo trước.",answer:["ngược lại","ngược"]}]},summary:["Muốn ghép hai chi tiết, em đặt trùng lỗ, luồn vít rồi vặn đai ốc.","Vặn cùng chiều kim đồng hồ để vít chặt, ngược chiều để tháo.","Tháo theo thứ tự ngược với khi lắp và xếp chi tiết vào hộp."]},{id:"cn4-lap-cai-du",title:"Lắp ghép mô hình cái đu",weeks:[22,23],learn:[{title:"Các bộ phận của cái đu",text:"Mô hình cái đu có ba bộ phận chính: giá đỡ, ghế đu và trục đu.",example:"🏗️ giá đỡ · 🪑 ghế đu · ➖ trục đu"},{title:"Lắp từng bộ phận",text:"Em lắp giá đỡ, lắp ghế đu, rồi dùng trục để treo ghế đu vào giá đỡ.",example:"1️⃣ giá đỡ ➜ 2️⃣ ghế đu ➜ 3️⃣ ghép lại"},{title:"Kiểm tra sản phẩm",text:"Lắp xong, em kiểm tra: giá đỡ đứng vững, ghế đu đung đưa nhẹ nhàng, các vít đã chặt.",example:"✅ vững · ✅ đung đưa · ✅ vít chặt"}],practice:[{questions:[{id:"cn4-lap-cai-du-01",type:"multi",q:"Đâu là bộ phận của mô hình cái đu?",explain:"Cái đu có giá đỡ, ghế đu và trục đu; bánh lái không có ở cái đu.",options:["Giá đỡ","Ghế đu","Trục đu","Bánh lái"],answers:[0,1,2]},{id:"cn4-lap-cai-du-02",type:"mc",q:"Bộ phận nào giữ cho cái đu đứng vững?",explain:"Giá đỡ là phần khung đứng trên mặt bàn, giữ cho đu vững.",options:["Ghế đu","Trục đu","Giá đỡ","Con vít nhỏ"],answer:2},{id:"cn4-lap-cai-du-03",type:"mc",q:"Bộ phận nào là chỗ ngồi của cái đu?",emoji:"🪑",explain:"Ghế đu là chỗ ngồi, được treo vào giá đỡ.",options:["Ghế đu","Giá đỡ","Trục đu"],answer:0},{id:"cn4-lap-cai-du-04",type:"tf",q:"Trục đu giúp ghế đu đung đưa được.",explain:"Đúng. Ghế đu treo vào trục nên đung đưa qua lại được.",answer:!0},{id:"cn4-lap-cai-du-05",type:"tf",q:"Mô hình cái đu chỉ cần một chi tiết là lắp xong.",explain:"Sai. Cái đu gồm nhiều chi tiết ghép thành giá đỡ, ghế đu và trục đu.",answer:!1},{id:"cn4-lap-cai-du-06",type:"fill",q:"Mô hình cái đu có ba bộ phận: giá đỡ, ghế đu và … đu.",explain:"Ba bộ phận chính là giá đỡ, ghế đu và trục đu.",answer:["trục"]},{id:"cn4-lap-cai-du-07",type:"match",q:"Nối bộ phận cái đu với tác dụng.",explain:"Mỗi bộ phận của cái đu có một tác dụng riêng.",pairs:[["Giá đỡ","Giữ đu đứng vững"],["Ghế đu","Làm chỗ ngồi"],["Trục đu","Treo ghế đung đưa"]]},{id:"cn4-lap-cai-du-08",type:"order",q:"Sắp xếp các bước lắp mô hình cái đu.",explain:"Lắp giá đỡ, lắp ghế, treo ghế vào trục rồi kiểm tra.",items:["Lắp giá đỡ","Lắp ghế đu","Lắp trục, treo ghế đu","Kiểm tra sản phẩm"]},{id:"cn4-lap-cai-du-09",type:"tf",q:"Lắp xong cái đu, em cần kiểm tra các con vít đã chặt chưa.",explain:"Đúng. Vít chặt thì cái đu mới chắc chắn.",answer:!0}]},{questions:[{id:"cn4-lap-cai-du-10",type:"mc",q:"Vì sao giá đỡ cần đứng vững?",explain:"Giá đỡ vững thì khi ghế đung đưa, cái đu không bị đổ.",options:["Để đu nhẹ hơn","Để đu có màu đẹp","Để đu không bị đổ"],answer:2},{id:"cn4-lap-cai-du-11",type:"mc",q:"Ghế đu không đung đưa được. Có thể do đâu?",explain:"Trục bị kẹt thì ghế không xoay quanh trục được.",options:["Ghế đu quá đẹp","Giá đỡ màu xanh","Trục bị kẹt cứng"],answer:2},{id:"cn4-lap-cai-du-12",type:"tf",q:"Hai chân giá đỡ nên lắp cân đối để đu không nghiêng.",explain:"Đúng. Hai chân cân đối giúp cái đu đứng thẳng, vững.",answer:!0},{id:"cn4-lap-cai-du-13",type:"multi",q:"Khi kiểm tra cái đu, em xem những gì?",explain:"Kiểm tra độ vững, độ đung đưa và các mối ghép.",options:["Giá đỡ đứng vững","Ghế đu đung đưa nhẹ","Vít đã vặn chặt","Hộp có nắp đẹp"],answers:[0,1,2]},{id:"cn4-lap-cai-du-14",type:"match",q:"Nối lỗi với cách sửa.",explain:"Tìm đúng chỗ lỗi rồi sửa ở chỗ đó.",pairs:[["Đu bị nghiêng","Chỉnh hai chân cân đối"],["Ghế bị kẹt","Nới trục cho quay nhẹ"],["Vít lỏng","Vặn chặt lại"]]},{id:"cn4-lap-cai-du-15",type:"order",q:"Sắp xếp các việc trước khi lắp cái đu.",explain:"Quan sát mẫu, chọn chi tiết, chuẩn bị dụng cụ rồi mới lắp.",items:["Quan sát mẫu cái đu","Chọn đủ chi tiết","Chuẩn bị tua-vít, cờ-lê","Bắt đầu lắp giá đỡ"]},{id:"cn4-lap-cai-du-16",type:"fill",q:"Bộ phận giữ cho cái đu đứng vững là … đỡ.",explain:"Giá đỡ giữ cho cái đu đứng vững.",answer:["giá"]},{id:"cn4-lap-cai-du-17",type:"tf",q:"Ghế đu nên gắn chặt cứng vào giá đỡ, không đung đưa.",explain:"Sai. Ghế đu phải đung đưa được quanh trục.",answer:!1},{id:"cn4-lap-cai-du-18",type:"mc",q:"Trục đu nối giữa hai bộ phận nào?",explain:"Trục đu gắn trên giá đỡ và treo ghế đu.",options:["Giá đỡ và ghế đu","Bánh xe và ghế","Hộp và nắp hộp"],answer:0}]},{questions:[{id:"cn4-lap-cai-du-19",type:"mc",q:"Hà lắp xong, cái đu bị nghiêng một bên. Hà nên làm gì?",explain:"Đu nghiêng thường do hai chân giá đỡ chưa cân đối.",options:["Tô màu lại","Bỏ ghế đu ra","Chỉnh lại giá đỡ","Để nguyên như vậy"],answer:2},{id:"cn4-lap-cai-du-20",type:"tf",q:"Đẩy nhẹ ghế mà ghế đung đưa đều là cái đu đã lắp tốt.",explain:"Đúng. Ghế đung đưa đều cho thấy trục và ghế lắp đúng.",answer:!0},{id:"cn4-lap-cai-du-21",type:"multi",q:"Nam muốn cái đu chắc hơn. Nam có thể làm gì?",explain:"Bỏ bớt vít làm cái đu lung lay hơn.",options:["Vặn chặt vít ở giá đỡ","Lắp thêm thanh giằng chân","Bỏ bớt vít ở chân đu","Kiểm tra lại các mối ghép"],answers:[0,1,3]},{id:"cn4-lap-cai-du-22",type:"match",q:"Nối câu hỏi kiểm tra với bộ phận cần xem.",explain:"Mỗi câu hỏi kiểm tra ứng với một bộ phận.",pairs:[["Có đứng vững không?","Giá đỡ"],["Có đung đưa không?","Ghế đu"],["Có quay nhẹ không?","Trục đu"]]},{id:"cn4-lap-cai-du-23",type:"order",q:"Sắp xếp các bước tháo mô hình cái đu.",explain:"Lắp giá đỡ trước nên khi tháo, giá đỡ được tháo sau.",items:["Tháo trục, lấy ghế đu ra","Tháo rời ghế đu","Tháo giá đỡ","Xếp chi tiết vào hộp"]},{id:"cn4-lap-cai-du-24",type:"mc",q:"Đẩy mạnh một chút là ghế đu rơi ra. Lỗi ở đâu?",explain:"Trục lắp lỏng thì ghế dễ tuột khỏi trục.",options:["Giá đỡ quá cao","Trục đu lắp lỏng","Ghế đu màu đỏ"],answer:1},{id:"cn4-lap-cai-du-25",type:"tf",q:"Mô hình cái đu dùng được cho em ngồi lên chơi như đu thật.",explain:"Sai. Mô hình nhỏ, chỉ để quan sát và thử nghiệm, ngồi lên sẽ gãy.",answer:!1},{id:"cn4-lap-cai-du-26",type:"fill",q:"Lắp xong, em đẩy nhẹ ghế để xem ghế có đung … không.",explain:"Ghế đung đưa nhẹ nhàng là lắp đúng.",answer:["đưa"]}]}],challenge:{questions:[{id:"cn4-lap-cai-du-08",type:"order",q:"Sắp xếp các bước lắp mô hình cái đu.",explain:"Lắp giá đỡ, lắp ghế, treo ghế vào trục rồi kiểm tra.",items:["Lắp giá đỡ","Lắp ghế đu","Lắp trục, treo ghế đu","Kiểm tra sản phẩm"]},{id:"cn4-lap-cai-du-27",type:"mc",q:"Cái đu ở công viên có bộ phận nào giống mô hình?",explain:"Đu thật cũng có giá đỡ, ghế đu và trục treo ghế.",options:["Bánh xe, còi","Màn hình, loa","Giá đỡ, ghế đu"],answer:2},{id:"cn4-lap-cai-du-28",type:"multi",q:"Ghế đu bị kẹt, không đung đưa. Có thể do đâu?",explain:"Màu sơn không làm ghế bị kẹt.",options:["Trục bị kẹt cứng","Ghế chạm vào giá đỡ","Ghế đu sơn màu vàng"],answers:[0,1]},{id:"cn4-lap-cai-du-29",type:"tf",q:"Lắp giá đỡ trước rồi mới treo ghế đu là hợp lí.",explain:"Đúng. Có giá đỡ vững rồi mới có chỗ treo ghế đu.",answer:!0},{id:"cn4-lap-cai-du-30",type:"match",q:"Nối việc làm với thời điểm.",explain:"Quan sát trước, vặn vít trong khi lắp, thử sau khi lắp.",pairs:[["Quan sát mẫu","Trước khi lắp"],["Vặn chặt vít","Trong khi lắp"],["Đẩy thử ghế đu","Sau khi lắp"]]},{id:"cn4-lap-cai-du-31",type:"mc",q:"Giá đỡ của Chi lung lay. Chi kiểm tra gì trước?",explain:"Giá đỡ lung lay thường do vít ở chân đu còn lỏng.",options:["Các vít ở chân đu","Nắp hộp đựng","Màu của ghế đu"],answer:0},{id:"cn4-lap-cai-du-32",type:"fill",q:"Bộ phận để treo ghế vào giá đỡ là … đu.",explain:"Trục đu treo ghế vào giá đỡ.",answer:["trục"]}]},summary:["Mô hình cái đu gồm giá đỡ, ghế đu và trục đu.","Lắp giá đỡ, lắp ghế đu, rồi treo ghế vào trục.","Lắp xong, kiểm tra đu đứng vững, ghế đung đưa nhẹ và vít đã chặt."]},{id:"cn4-lap-robot",title:"Lắp ghép mô hình rô-bốt",weeks:[24,25],learn:[{title:"Các bộ phận của rô-bốt",text:"Mô hình rô-bốt thường có đầu, thân, tay và chân. Mỗi bộ phận được lắp từ vài chi tiết.",example:"🤖 đầu · thân · hai tay · hai chân"},{title:"Lắp từ dưới lên",text:"Một cách lắp dễ là lắp chân trước làm chỗ đứng, sau đó lắp thân, rồi gắn đầu và tay.",example:"🦵 chân ➜ 🧱 thân ➜ 🙂 đầu ➜ 💪 tay"},{title:"Rô-bốt trong đời sống",text:"Rô-bốt thật giúp con người làm nhiều việc như hút bụi, lắp ráp ô tô, chở hàng trong kho.",example:"🧹 hút bụi · 🚗 nhà máy · 📦 kho hàng"}],practice:[{questions:[{id:"cn4-lap-robot-01",type:"multi",q:"Đâu là bộ phận của mô hình rô-bốt?",emoji:"🤖",explain:"Rô-bốt có đầu, thân, tay và chân; mái chèo là của con thuyền.",options:["Đầu","Thân","Tay","Mái chèo"],answers:[0,1,2]},{id:"cn4-lap-robot-02",type:"mc",q:"Bộ phận nào giúp rô-bốt đứng được?",explain:"Chân ở dưới cùng, đỡ cả rô-bốt đứng vững.",options:["Tay","Đầu","Chân","Ăng-ten"],answer:2},{id:"cn4-lap-robot-03",type:"tf",q:"Rô-bốt hút bụi giúp con người làm việc nhà.",emoji:"🧹",explain:"Đúng. Rô-bốt hút bụi tự di chuyển và làm sạch sàn nhà.",answer:!0},{id:"cn4-lap-robot-04",type:"tf",q:"Mô hình rô-bốt lắp từ bộ lắp ghép tự đi lại được như người.",explain:"Sai. Mô hình này chỉ đứng yên, không có động cơ để tự đi.",answer:!1},{id:"cn4-lap-robot-05",type:"fill",q:"Mô hình rô-bốt có đầu, thân, tay và … .",explain:"Bốn phần của rô-bốt là đầu, thân, tay và chân.",answer:["chân"]},{id:"cn4-lap-robot-06",type:"match",q:"Nối rô-bốt với việc nó làm.",explain:"Rô-bốt giúp con người làm nhiều việc nặng, việc lặp lại.",pairs:[["Rô-bốt hút bụi","Làm sạch sàn nhà"],["Rô-bốt trong nhà máy","Lắp ráp ô tô"],["Rô-bốt trong kho","Chở hàng"]]},{id:"cn4-lap-robot-07",type:"order",q:"Sắp xếp một cách lắp mô hình rô-bốt.",explain:"Lắp chân trước làm chỗ đứng, rồi thân, đầu và tay.",items:["Lắp chân","Lắp thân lên chân","Gắn đầu","Gắn hai tay"]},{id:"cn4-lap-robot-08",type:"mc",q:"Lắp chân rô-bốt trước để làm gì?",explain:"Chân là chỗ đứng, có chân rồi mới lắp thân lên trên.",options:["Cho nhẹ hơn","Làm chỗ đứng","Để dễ tô màu"],answer:1},{id:"cn4-lap-robot-09",type:"tf",q:"Rô-bốt là một sản phẩm công nghệ.",explain:"Đúng. Rô-bốt do con người thiết kế và làm ra.",answer:!0}]},{questions:[{id:"cn4-lap-robot-10",type:"mc",q:"Hai tay rô-bốt nên lắp thế nào?",explain:"Hai tay cân đối hai bên giúp rô-bốt đẹp và không nghiêng.",options:["Cả hai ở một bên","Cân đối hai bên thân","Gắn lên đỉnh đầu"],answer:1},{id:"cn4-lap-robot-11",type:"tf",q:"Nếu chân lắp lỏng, rô-bốt dễ bị đổ.",explain:"Đúng. Chân là chỗ đứng, lỏng thì rô-bốt lung lay, dễ đổ.",answer:!0},{id:"cn4-lap-robot-12",type:"multi",q:"Rô-bốt thật có thể giúp con người việc gì?",explain:"Rô-bốt giúp làm việc, nhưng việc học là của em.",options:["Hút bụi sàn nhà","Lắp ráp ô tô","Chở hàng trong kho","Học bài thay em"],answers:[0,1,2]},{id:"cn4-lap-robot-13",type:"match",q:"Nối bộ phận rô-bốt với vị trí lắp.",explain:"Chân ở dưới, thân ở giữa, đầu ở trên cùng.",pairs:[["Chân","Dưới cùng"],["Thân","Ở giữa"],["Đầu","Trên cùng"]]},{id:"cn4-lap-robot-14",type:"fill",q:"Bộ phận ở giữa, nối đầu với chân rô-bốt là … .",explain:"Thân nằm giữa, nối đầu ở trên với chân ở dưới.",answer:["thân"]},{id:"cn4-lap-robot-15",type:"tf",q:"Lắp xong, em kiểm tra rô-bốt đứng vững và vít đã chặt.",explain:"Đúng. Kiểm tra giúp phát hiện chỗ lỏng để sửa.",answer:!0},{id:"cn4-lap-robot-16",type:"tf",q:"Rô-bốt lắp xong bị nghiêng thì không cần sửa.",explain:"Sai. Rô-bốt nghiêng dễ đổ, em cần chỉnh lại chân hoặc thân.",answer:!1},{id:"cn4-lap-robot-17",type:"order",q:"Sắp xếp các bước làm mô hình rô-bốt.",explain:"Quan sát, chọn chi tiết, lắp từng bộ phận, ghép lại rồi kiểm tra.",items:["Quan sát mẫu rô-bốt","Chọn đủ chi tiết","Lắp từng bộ phận","Ghép các bộ phận lại","Kiểm tra sản phẩm"]},{id:"cn4-lap-robot-18",type:"mc",q:"Rô-bốt hút bụi thuộc nhóm nào?",explain:"Rô-bốt do con người làm ra nên là sản phẩm công nghệ.",options:["Sản phẩm công nghệ","Đối tượng tự nhiên"],answer:0}]},{questions:[{id:"cn4-lap-robot-19",type:"mc",q:"Rô-bốt của Khoa bị đổ về phía trước. Khoa sửa phần nào?",explain:"Rô-bốt đổ thường do chân lắp lệch hoặc lỏng.",options:["Phần mắt","Màu của tay","Phần chân"],answer:2},{id:"cn4-lap-robot-20",type:"multi",q:"Vy muốn rô-bốt đứng vững hơn. Vy có thể làm gì?",explain:"Đầu to, nặng ở trên cao làm rô-bốt dễ đổ hơn.",options:["Lắp chân rộng hơn","Vặn chặt vít ở chân","Gắn đầu thật to, nặng"],answers:[0,1]},{id:"cn4-lap-robot-21",type:"tf",q:"Có thể thêm chi tiết để trang trí rô-bốt theo ý mình.",explain:"Đúng. Em được sáng tạo thêm, miễn rô-bốt vẫn chắc chắn.",answer:!0},{id:"cn4-lap-robot-22",type:"match",q:"Nối lỗi với cách sửa.",explain:"Tìm đúng chỗ lỗi rồi sửa ở chỗ đó.",pairs:[["Tay rô-bốt rơi ra","Vặn chặt vít ở vai"],["Rô-bốt bị đổ","Chỉnh lại chân"],["Đầu bị lệch","Lắp lại cho thẳng"]]},{id:"cn4-lap-robot-23",type:"order",q:"Sắp xếp các bước tháo mô hình rô-bốt.",explain:"Tay và đầu lắp sau nên được tháo trước, chân tháo sau cùng.",items:["Tháo hai tay","Tháo đầu","Tháo thân khỏi chân","Xếp chi tiết vào hộp"]},{id:"cn4-lap-robot-24",type:"tf",q:"Rô-bốt làm thay được mọi việc nên con người không cần học nữa.",explain:"Sai. Con người phải học để thiết kế, điều khiển và sửa rô-bốt.",answer:!1},{id:"cn4-lap-robot-25",type:"mc",q:"Ngọc thiếu một con vít để lắp tay rô-bốt. Ngọc nên làm gì?",explain:"Các chi tiết còn lại thường nằm trong hộp đựng.",options:["Bỏ luôn cánh tay","Dùng kẹo dán vào","Tìm trong hộp đựng"],answer:2},{id:"cn4-lap-robot-26",type:"fill",q:"Máy tự làm việc thay con người, như hút bụi, gọi là … .",explain:"Rô-bốt là máy có thể tự làm một số việc thay con người.",answer:["rô-bốt","robot","rô bốt"]}]}],challenge:{questions:[{id:"cn4-lap-robot-17",type:"order",q:"Sắp xếp các bước làm mô hình rô-bốt.",explain:"Quan sát, chọn chi tiết, lắp từng bộ phận, ghép lại rồi kiểm tra.",items:["Quan sát mẫu rô-bốt","Chọn đủ chi tiết","Lắp từng bộ phận","Ghép các bộ phận lại","Kiểm tra sản phẩm"]},{id:"cn4-lap-robot-27",type:"mc",q:"Rô-bốt trong nhà máy ô tô thường làm việc gì?",explain:"Trong nhà máy, rô-bốt giúp lắp ráp xe nhanh và chính xác.",options:["Bán vé xem phim","Dạy học sinh","Lắp ráp xe"],answer:2},{id:"cn4-lap-robot-28",type:"tf",q:"Muốn rô-bốt đứng vững, chân cần chắc và cân đối.",explain:"Đúng. Chân chắc, cân đối thì rô-bốt không nghiêng, không đổ.",answer:!0},{id:"cn4-lap-robot-29",type:"multi",q:"Việc nào cần làm sau khi lắp xong rô-bốt?",explain:"Hộp đựng cần giữ lại để cất chi tiết sau khi tháo.",options:["Kiểm tra độ vững","Kiểm tra vít đã chặt","Vứt hộp đựng đi"],answers:[0,1]},{id:"cn4-lap-robot-30",type:"match",q:"Nối bộ phận với vị trí trên rô-bốt.",explain:"Thân ở giữa; đầu ở trên, tay hai bên, chân ở dưới.",pairs:[["Đầu","Phía trên thân"],["Tay","Hai bên thân"],["Chân","Phía dưới thân"]]},{id:"cn4-lap-robot-31",type:"fill",q:"Khi lắp rô-bốt, em nên lắp phần … trước để làm chỗ đứng.",explain:"Chân là chỗ đứng nên lắp trước.",answer:["chân"]},{id:"cn4-lap-robot-32",type:"mc",q:"Rô-bốt bị nghiêng sang trái. Có thể do đâu?",explain:"Chân lắp lệch làm rô-bốt nghiêng về một bên.",options:["Đầu sơn màu đỏ","Tay quá đẹp","Chân lắp lệch"],answer:2}]},summary:["Mô hình rô-bốt có đầu, thân, tay và chân.","Lắp chân trước làm chỗ đứng, rồi lắp thân, đầu và tay.","Rô-bốt là sản phẩm công nghệ giúp con người làm nhiều việc."]}]},{id:"do-choi-dan-gian",title:"Đồ chơi dân gian",lessons:[{id:"cn4-do-choi-dan-gian",title:"Đồ chơi dân gian quanh em",weeks:[26,27],learn:[{title:"Đồ chơi dân gian là gì?",text:"Đồ chơi dân gian là đồ chơi truyền thống, thường được làm bằng tay từ vật liệu gần gũi như tre, giấy, bột gạo.",example:"🪁 diều · 🏮 đèn · 🌀 chong chóng"},{title:"Một số đồ chơi dân gian",text:"Chong chóng, diều, đèn ông sao, tò he, trống bỏi, con quay là những đồ chơi dân gian quen thuộc.",example:"🥁 trống bỏi · 🎨 tò he · 🪀 con quay"},{title:"Giữ gìn nét đẹp xưa",text:"Đèn ông sao gắn với Tết Trung thu. Tò he được nặn từ bột gạo nhuộm màu. Chơi đồ chơi dân gian giúp em yêu nét đẹp truyền thống.",example:"🌕 Trung thu ➜ ⭐ đèn ông sao"}],practice:[{questions:[{id:"cn4-do-choi-dan-gian-01",type:"multi",q:"Đâu là đồ chơi dân gian?",explain:"Máy chơi game là đồ chơi điện tử hiện đại.",options:["Diều giấy","Tò he","Trống bỏi","Máy chơi game"],answers:[0,1,2]},{id:"cn4-do-choi-dan-gian-02",type:"mc",q:"Đèn ông sao thường gắn với dịp nào?",emoji:"🌕",explain:"Đêm Trung thu, các bạn nhỏ thường rước đèn ông sao.",options:["Ngày khai giảng","Ngày sinh nhật","Tết Trung thu"],answer:2},{id:"cn4-do-choi-dan-gian-03",type:"mc",q:"Tò he được nặn từ gì?",explain:"Tò he được nặn từ bột gạo nhuộm màu.",options:["Nhựa cứng","Bột gạo","Sắt thép","Thủy tinh"],answer:1},{id:"cn4-do-choi-dan-gian-04",type:"tf",q:"Chong chóng là một đồ chơi dân gian.",emoji:"🌀",explain:"Đúng. Chong chóng làm từ giấy và que, quay nhờ gió.",answer:!0},{id:"cn4-do-choi-dan-gian-05",type:"tf",q:"Đồ chơi dân gian chỉ làm được bằng máy móc hiện đại.",explain:"Sai. Đồ chơi dân gian thường được làm bằng tay từ vật liệu gần gũi.",answer:!1},{id:"cn4-do-choi-dan-gian-06",type:"fill",q:"Đồ chơi nặn từ bột gạo nhuộm màu, hình con vật, gọi là tò … .",explain:"Tò he nặn từ bột gạo nhuộm màu.",answer:["he"]},{id:"cn4-do-choi-dan-gian-07",type:"match",q:"Nối đồ chơi với vật liệu thường dùng.",explain:"Đồ chơi dân gian làm từ vật liệu gần gũi quanh em.",pairs:[["Tò he","Bột gạo"],["Chong chóng","Giấy và que"],["Con quay","Gỗ"]]},{id:"cn4-do-choi-dan-gian-08",type:"mc",q:"Đồ chơi nào bay lên cao nhờ gió?",emoji:"🪁",explain:"Diều bay lên cao nhờ gió.",options:["Con quay","Trống bỏi","Tò he","Diều"],answer:3},{id:"cn4-do-choi-dan-gian-09",type:"tf",q:"Trống bỏi phát ra tiếng kêu khi em xoay cán qua lại.",emoji:"🥁",explain:"Đúng. Xoay cán, hai hạt nhỏ đập vào mặt trống tạo ra tiếng kêu.",answer:!0}]},{questions:[{id:"cn4-do-choi-dan-gian-10",type:"mc",q:"Vì sao chong chóng quay được?",explain:"Gió thổi vào cánh làm chong chóng quay.",options:["Nhờ pin","Nhờ điện","Nhờ gió"],answer:2},{id:"cn4-do-choi-dan-gian-11",type:"multi",q:"Vật liệu nào thường dùng làm đồ chơi dân gian?",explain:"Đồ chơi dân gian dùng vật liệu tự nhiên, gần gũi như tre, giấy, bột gạo.",options:["Tre","Giấy","Bột gạo","Nhựa đúc bằng máy"],answers:[0,1,2]},{id:"cn4-do-choi-dan-gian-12",type:"tf",q:"Chơi đồ chơi dân gian giúp em biết thêm về nét đẹp truyền thống.",explain:"Đúng. Đồ chơi dân gian gắn với phong tục, lễ hội của dân tộc.",answer:!0},{id:"cn4-do-choi-dan-gian-13",type:"match",q:"Nối đồ chơi với cách chơi.",explain:"Mỗi đồ chơi dân gian có một cách chơi riêng.",pairs:[["Diều","Thả cho bay cao"],["Con quay","Quấn dây rồi thả"],["Chong chóng","Đón gió cho quay"],["Trống bỏi","Xoay cán cho kêu"]]},{id:"cn4-do-choi-dan-gian-14",type:"order",q:"Sắp xếp các bước chơi con quay.",explain:"Quấn dây, giữ đầu dây, thả và giật dây cho con quay xoay.",items:["Quấn dây quanh con quay","Cầm chắc đầu dây","Thả con quay, giật dây","Xem con quay xoay tít"]},{id:"cn4-do-choi-dan-gian-15",type:"fill",q:"Đồ chơi có khung nan tre, dán giấy, bay cao nhờ gió là … .",explain:"Diều có khung nan tre, dán giấy, bay nhờ gió.",answer:["diều","cái diều","con diều"]},{id:"cn4-do-choi-dan-gian-16",type:"mc",q:"Đồ chơi nào KHÔNG phải đồ chơi dân gian?",explain:"Xe điều khiển chạy bằng pin, là đồ chơi hiện đại.",options:["Đèn ông sao","Con quay gỗ","Xe điều khiển","Trống bỏi"],answer:2},{id:"cn4-do-choi-dan-gian-17",type:"tf",q:"Đồ chơi dân gian thường đắt và khó tìm vật liệu.",explain:"Sai. Đồ chơi dân gian thường rẻ, làm từ vật liệu dễ tìm.",answer:!1},{id:"cn4-do-choi-dan-gian-18",type:"mc",q:"Đêm Trung thu, các bạn nhỏ thường rước gì?",explain:"Rước đèn ông sao là nét đẹp của đêm Trung thu.",options:["Con diều sáo","Đèn ông sao","Trống cơm"],answer:1}]},{questions:[{id:"cn4-do-choi-dan-gian-19",type:"multi",q:"Lan muốn làm đồ chơi dân gian từ giấy. Lan có thể làm gì?",explain:"Tò he nặn từ bột gạo, không làm từ giấy.",options:["Chong chóng","Diều giấy","Đèn ông sao","Tò he"],answers:[0,1,2]},{id:"cn4-do-choi-dan-gian-20",type:"mc",q:"Bình muốn chơi chong chóng mà trời lặng gió. Bình làm gì?",explain:"Cầm chong chóng chạy nhẹ ở sân rộng sẽ tạo ra gió cho cánh quay.",options:["Đổ nước vào","Cầm chạy nhẹ","Cắm vào ổ điện"],answer:1},{id:"cn4-do-choi-dan-gian-21",type:"tf",q:"Khi chơi con quay, em nên đứng xa các bạn để không va vào.",explain:"Đúng. Con quay xoay nhanh, đứng xa giúp không ai bị va.",answer:!0},{id:"cn4-do-choi-dan-gian-22",type:"match",q:"Nối đồ chơi với dịp hoặc nơi chơi phù hợp.",explain:"Chọn đúng dịp, đúng nơi thì chơi vui và an toàn.",pairs:[["Đèn ông sao","Đêm Trung thu"],["Diều","Bãi đất rộng, lộng gió"],["Con quay","Mặt sân phẳng"]]},{id:"cn4-do-choi-dan-gian-23",type:"order",q:"Sắp xếp các bước chơi chong chóng.",explain:"Cầm cán, hướng cánh về phía gió để chong chóng quay.",items:["Cầm cán chong chóng","Hướng cánh về phía gió","Ngắm chong chóng quay"]},{id:"cn4-do-choi-dan-gian-24",type:"tf",q:"Có thể ném con quay về phía bạn cho vui.",explain:"Sai. Con quay cứng, ném vào bạn có thể làm bạn đau.",answer:!1},{id:"cn4-do-choi-dan-gian-25",type:"mc",q:"Hà nói: “Đồ chơi dân gian cũ rồi, không nên chơi nữa.” Em thấy sao?",explain:"Đồ chơi dân gian vẫn vui, rẻ và giúp em yêu nét đẹp truyền thống.",options:["Hà nói đúng","Hà chưa đúng","Chỉ nên chơi game"],answer:1},{id:"cn4-do-choi-dan-gian-26",type:"fill",q:"Đồ chơi dân gian thường được làm bằng … từ vật liệu gần gũi.",explain:"Người xưa làm đồ chơi bằng tay từ tre, giấy, bột gạo.",answer:["tay"]}]}],challenge:{questions:[{id:"cn4-do-choi-dan-gian-13",type:"match",q:"Nối đồ chơi với cách chơi.",explain:"Mỗi đồ chơi dân gian có một cách chơi riêng.",pairs:[["Diều","Thả cho bay cao"],["Con quay","Quấn dây rồi thả"],["Chong chóng","Đón gió cho quay"],["Trống bỏi","Xoay cán cho kêu"]]},{id:"cn4-do-choi-dan-gian-27",type:"mc",q:"Vì sao nên thả diều ở bãi đất rộng?",explain:"Bãi đất rộng xa dây điện và xe cộ nên thả diều an toàn hơn.",options:["Để diều đẹp hơn","Để diều nhẹ hơn","Để an toàn hơn"],answer:2},{id:"cn4-do-choi-dan-gian-28",type:"tf",q:"Đèn ông sao thường có năm cánh.",emoji:"⭐",explain:"Đúng. Đèn ông sao có hình ngôi sao năm cánh.",answer:!0},{id:"cn4-do-choi-dan-gian-29",type:"multi",q:"Đâu là lợi ích khi tự làm đồ chơi dân gian?",explain:"Tự làm đồ chơi giúp em khéo tay, tiết kiệm và yêu truyền thống.",options:["Khéo tay hơn","Tiết kiệm","Yêu nét đẹp truyền thống","Tốn nhiều tiền mua"],answers:[0,1,2]},{id:"cn4-do-choi-dan-gian-30",type:"fill",q:"Đèn ông sao gắn với Tết … .",explain:"Đèn ông sao được rước vào đêm Tết Trung thu.",answer:["Trung thu","Trung Thu"]},{id:"cn4-do-choi-dan-gian-31",type:"order",q:"Sắp xếp các bước làm một đồ chơi dân gian.",explain:"Chọn đồ chơi, chuẩn bị, làm từng phần, lắp ghép rồi chơi thử.",items:["Chọn đồ chơi muốn làm","Chuẩn bị vật liệu, dụng cụ","Làm từng bộ phận","Lắp ghép, trang trí","Chơi thử, sửa lại"]},{id:"cn4-do-choi-dan-gian-32",type:"mc",q:"Đồ chơi nào phát ra tiếng kêu khi xoay cán?",explain:"Trống bỏi kêu khi em xoay cán qua lại.",options:["Tò he","Diều giấy","Trống bỏi","Con quay"],answer:2}]},summary:["Đồ chơi dân gian được làm bằng tay từ vật liệu gần gũi như tre, giấy, bột gạo.","Chong chóng, diều, đèn ông sao, tò he, trống bỏi, con quay là đồ chơi dân gian.","Chơi đồ chơi dân gian an toàn và giữ gìn nét đẹp truyền thống."]},{id:"cn4-chong-chong",title:"Làm chong chóng",weeks:[28,29],learn:[{title:"Bộ phận của chong chóng",text:"Chong chóng gồm cánh, trục quay và cán cầm. Gió thổi vào cánh làm chong chóng quay.",example:"🌀 cánh · 📍 trục · 🥢 cán"},{title:"Vật liệu và dụng cụ",text:"Em cần giấy hình vuông, que tre hoặc ống hút làm cán, ghim nhỏ làm trục, kéo, thước và bút chì.",example:"📄 giấy · ✂️ kéo · 📏 thước · 🥢 que"},{title:"Các bước làm",text:"Kẻ hai đường chéo, cắt từ bốn góc vào gần tâm, gập bốn đầu cánh vào tâm rồi gắn trục và cán. Nhờ người lớn giúp khi gắn trục.",example:"✏️ kẻ ➜ ✂️ cắt ➜ 🔄 gập ➜ 📍 gắn"}],practice:[{questions:[{id:"cn4-chong-chong-01",type:"multi",q:"Chong chóng gồm những bộ phận nào?",emoji:"🌀",explain:"Chong chóng có cánh, trục quay và cán cầm.",options:["Cánh","Trục quay","Cán cầm","Bánh xe"],answers:[0,1,2]},{id:"cn4-chong-chong-02",type:"mc",q:"Chong chóng quay được nhờ đâu?",explain:"Gió thổi vào cánh làm chong chóng quay.",options:["Pin","Gió","Điện","Nam châm"],answer:1},{id:"cn4-chong-chong-03",type:"tf",q:"Giấy làm chong chóng thường cắt thành hình vuông.",explain:"Đúng. Từ tờ giấy hình vuông, em cắt và gập thành cánh chong chóng.",answer:!0},{id:"cn4-chong-chong-04",type:"fill",q:"Bộ phận để em cầm khi chơi chong chóng là … cầm.",explain:"Cán cầm thường làm bằng que tre hoặc ống hút.",answer:["cán"]},{id:"cn4-chong-chong-05",type:"mc",q:"Dụng cụ nào dùng để cắt giấy?",emoji:"✂️",explain:"Kéo dùng để cắt giấy, nhớ cắt cẩn thận.",options:["Kéo","Thước","Bút chì","Hồ dán"],answer:0},{id:"cn4-chong-chong-06",type:"tf",q:"Khi cắt từ góc vào, em phải cắt đứt tới tận tâm tờ giấy.",explain:"Sai. Chỉ cắt đến gần tâm, nếu cắt tới tâm các cánh sẽ rời nhau.",answer:!1},{id:"cn4-chong-chong-07",type:"order",q:"Sắp xếp các bước làm chong chóng.",explain:"Kẻ, cắt, gập cánh rồi gắn trục và cán.",items:["Kẻ hai đường chéo","Cắt từ bốn góc vào gần tâm","Gập bốn đầu cánh vào tâm","Gắn trục và cán"]},{id:"cn4-chong-chong-08",type:"match",q:"Nối vật liệu với bộ phận chong chóng.",explain:"Giấy làm cánh, que làm cán, ghim nhỏ làm trục.",pairs:[["Giấy hình vuông","Cánh"],["Que tre","Cán cầm"],["Ghim nhỏ","Trục quay"]]},{id:"cn4-chong-chong-09",type:"tf",q:"Khi đưa kéo cho bạn, em cầm phía lưỡi và đưa cán kéo về phía bạn.",explain:"Đúng. Đưa cán kéo về phía bạn để bạn cầm không bị đứt tay.",answer:!0}]},{questions:[{id:"cn4-chong-chong-10",type:"mc",q:"Vì sao không cắt tới tận tâm tờ giấy?",explain:"Phần giữa không cắt giữ cho các cánh còn dính với nhau.",options:["Để giấy đẹp hơn","Để cắt nhanh hơn","Để cánh không rời"],answer:2},{id:"cn4-chong-chong-11",type:"mc",q:"Kẻ hai đường chéo tờ giấy vuông để làm gì?",explain:"Hai đường chéo cắt nhau ở tâm và là đường để cắt.",options:["Trang trí cho đẹp","Đo chiều dài","Tìm tâm tờ giấy"],answer:2},{id:"cn4-chong-chong-12",type:"tf",q:"Các cánh gập đều nhau thì chong chóng quay đều hơn.",explain:"Đúng. Cánh đều nhau giúp chong chóng cân, quay đều.",answer:!0},{id:"cn4-chong-chong-13",type:"multi",q:"Việc nào giúp em dùng kéo an toàn?",explain:"Chĩa mũi kéo vào bạn rất nguy hiểm.",options:["Cắt chậm, cẩn thận","Không vừa cắt vừa đùa","Chĩa mũi kéo vào bạn","Cất kéo sau khi dùng"],answers:[0,1,3]},{id:"cn4-chong-chong-14",type:"match",q:"Nối bước làm với dụng cụ.",explain:"Mỗi bước dùng một dụng cụ phù hợp.",pairs:[["Kẻ đường chéo","Thước, bút chì"],["Cắt giấy","Kéo"],["Trang trí cánh","Bút màu"]]},{id:"cn4-chong-chong-15",type:"fill",q:"Khi chơi, em hướng cánh chong chóng về phía có … .",explain:"Gió thổi vào cánh thì chong chóng mới quay.",answer:["gió"]},{id:"cn4-chong-chong-16",type:"tf",q:"Chong chóng giấy để ngoài mưa vẫn bền như mới.",explain:"Sai. Giấy gặp nước sẽ nhũn, rách.",answer:!1},{id:"cn4-chong-chong-17",type:"order",q:"Sắp xếp các bước gắn cánh vào cán.",explain:"Chồng đầu cánh ở tâm, xuyên trục, gắn vào cán rồi thử.",items:["Gập các đầu cánh chồng ở tâm","Xuyên trục qua tâm cánh","Gắn trục vào đầu cán","Xoay thử xem cánh quay không"]},{id:"cn4-chong-chong-18",type:"mc",q:"Cắt từ bốn góc vào, tờ giấy có bao nhiêu đầu nhọn?",explain:"Mỗi đường cắt chia một góc thành hai đầu nhọn, nên có 8 đầu.",options:["4","8","6"],answer:1}]},{questions:[{id:"cn4-chong-chong-19",type:"mc",q:"Chong chóng của Minh quay chậm, cánh bị kẹt. Minh làm gì?",explain:"Trục quá chặt làm cánh kẹt, nới trục cho cánh quay nhẹ.",options:["Nới trục ra","Bỏ bớt một cánh","Dán thêm băng dính"],answer:0},{id:"cn4-chong-chong-20",type:"multi",q:"Thảo muốn chong chóng đẹp hơn. Thảo có thể làm gì?",explain:"Cắt rời các cánh thì chong chóng hỏng.",options:["Dùng giấy nhiều màu","Vẽ hoa văn lên cánh","Cắt rời các cánh"],answers:[0,1]},{id:"cn4-chong-chong-21",type:"tf",q:"Không có que tre, có thể dùng ống hút làm cán chong chóng.",explain:"Đúng. Ống hút nhẹ, cứng vừa đủ để làm cán.",answer:!0},{id:"cn4-chong-chong-22",type:"match",q:"Nối lỗi với cách sửa.",explain:"Tìm chỗ lỗi rồi sửa đúng chỗ đó.",pairs:[["Cánh bị rách","Làm lại cánh mới"],["Cánh gập lệch","Gập lại cho đều"],["Trục quá chặt","Nới trục ra"]]},{id:"cn4-chong-chong-23",type:"order",q:"Sắp xếp các bước trước khi cắt giấy làm chong chóng.",explain:"Chọn giấy, kẻ đường chéo, đánh dấu chỗ dừng rồi mới cắt.",items:["Chọn tờ giấy hình vuông","Kẻ hai đường chéo","Đánh dấu điểm dừng gần tâm","Cắt theo đường kẻ"]},{id:"cn4-chong-chong-24",type:"tf",q:"Chơi chong chóng, em có thể chạy ra lòng đường cho nhiều gió.",explain:"Sai. Lòng đường có xe cộ, rất nguy hiểm.",answer:!1},{id:"cn4-chong-chong-25",type:"mc",q:"Vì sao không nên để chong chóng giấy nơi ẩm ướt?",explain:"Giấy hút nước nên dễ nhũn và rách.",options:["Giấy sẽ hóa gỗ","Giấy dễ nhũn, rách","Cánh sẽ kêu to"],answer:1},{id:"cn4-chong-chong-26",type:"number",q:"Tờ giấy hình vuông có mấy đường chéo?",explain:"Hình vuông có 2 đường chéo, cắt nhau ở tâm.",answer:2}]}],challenge:{questions:[{id:"cn4-chong-chong-07",type:"order",q:"Sắp xếp các bước làm chong chóng.",explain:"Kẻ, cắt, gập cánh rồi gắn trục và cán.",items:["Kẻ hai đường chéo","Cắt từ bốn góc vào gần tâm","Gập bốn đầu cánh vào tâm","Gắn trục và cán"]},{id:"cn4-chong-chong-27",type:"mc",q:"Cắt bốn góc giấy vào gần tâm. Em gập mấy đầu vào tâm?",explain:"Có 8 đầu nhọn, em gập cách một đầu, tức là 4 đầu.",options:["4","2","8"],answer:0},{id:"cn4-chong-chong-28",type:"tf",q:"Gió càng mạnh thì chong chóng giấy thường quay càng nhanh.",explain:"Đúng. Gió mạnh đẩy cánh nhiều hơn nên chong chóng quay nhanh hơn.",answer:!0},{id:"cn4-chong-chong-29",type:"multi",q:"Bạn nào làm chong chóng an toàn?",explain:"Cầm kéo chạy nhảy dễ ngã, bị kéo đâm vào người.",options:["An nhờ người lớn gắn trục","Bình cắt giấy chậm rãi","Chi cầm kéo chạy nhảy"],answers:[0,1]},{id:"cn4-chong-chong-08",type:"match",q:"Nối vật liệu với bộ phận chong chóng.",explain:"Giấy làm cánh, que làm cán, ghim nhỏ làm trục.",pairs:[["Giấy hình vuông","Cánh"],["Que tre","Cán cầm"],["Ghim nhỏ","Trục quay"]]},{id:"cn4-chong-chong-30",type:"fill",q:"Bộ phận của chong chóng hứng gió để quay là … .",explain:"Cánh hứng gió nên chong chóng quay.",answer:["cánh","cánh chong chóng"]},{id:"cn4-chong-chong-31",type:"mc",q:"Chong chóng gập lệch thì quay không đều. Vì sao?",explain:"Các cánh lệch nhau làm chong chóng không cân nên quay không đều.",options:["Cánh lệch nhau","Cán màu xanh","Giấy quá đẹp"],answer:0}]},summary:["Chong chóng gồm cánh, trục quay và cán cầm, quay được nhờ gió.","Kẻ đường chéo, cắt từ góc vào gần tâm, gập cánh rồi gắn trục và cán.","Dùng kéo cẩn thận và chơi chong chóng ở nơi an toàn."]},{id:"cn4-dieu-giay",title:"Làm diều giấy",weeks:[30,32],learn:[{title:"Bộ phận của diều",text:"Diều gồm khung diều, thân diều, đuôi diều và dây diều.",example:"🪁 khung · thân · đuôi · dây"},{title:"Làm diều",text:"Làm khung bằng nan tre nhẹ, dán giấy làm thân, gắn đuôi cho diều bay cân, rồi buộc dây để thả.",example:"🎋 nan tre ➜ 📄 giấy ➜ 🎀 đuôi ➜ 🧵 dây"},{title:"Thả diều an toàn",text:"Thả diều ở bãi đất rộng, xa đường dây điện và đường giao thông. Diều vướng dây điện thì không tự gỡ, hãy báo người lớn.",example:"✅ bãi rộng · ⛔ dây điện · ⛔ lòng đường"}],practice:[{questions:[{id:"cn4-dieu-giay-01",type:"multi",q:"Đâu là bộ phận của diều?",emoji:"🪁",explain:"Diều có khung, thân, đuôi và dây diều.",options:["Khung diều","Đuôi diều","Dây diều","Bánh xe"],answers:[0,1,2]},{id:"cn4-dieu-giay-02",type:"mc",q:"Nơi nào an toàn để thả diều?",explain:"Bãi đất rộng, xa dây điện và xe cộ là nơi thả diều an toàn.",options:["Lòng đường","Bãi đất rộng","Gần cột điện","Trên mái nhà"],answer:1},{id:"cn4-dieu-giay-03",type:"tf",q:"Diều vướng vào dây điện, em có thể trèo lên gỡ.",emoji:"⚡",explain:"Sai. Rất nguy hiểm vì có thể bị điện giật; em báo người lớn.",answer:!1},{id:"cn4-dieu-giay-04",type:"fill",q:"Bộ phận giúp diều bay cân, dài phía sau là … diều.",explain:"Đuôi diều giúp diều bay cân, không bị xoay tròn.",answer:["đuôi"]},{id:"cn4-dieu-giay-05",type:"mc",q:"Khung diều thường làm bằng gì?",explain:"Nan tre nhẹ và dẻo nên hay dùng làm khung diều.",options:["Nan tre","Gạch","Đá","Sắt nặng"],answer:0},{id:"cn4-dieu-giay-06",type:"tf",q:"Diều bay lên được nhờ có gió.",explain:"Đúng. Gió nâng diều bay lên cao.",answer:!0},{id:"cn4-dieu-giay-07",type:"match",q:"Nối bộ phận diều với vật liệu.",explain:"Khung bằng nan tre, thân bằng giấy, dây diều để giữ diều.",pairs:[["Khung diều","Nan tre"],["Thân diều","Giấy"],["Dây diều","Cuộn dây"]]},{id:"cn4-dieu-giay-08",type:"order",q:"Sắp xếp các bước làm diều.",explain:"Làm khung, dán thân, gắn đuôi rồi buộc dây.",items:["Làm khung bằng nan tre","Dán giấy làm thân diều","Gắn đuôi diều","Buộc dây diều"]},{id:"cn4-dieu-giay-09",type:"tf",q:"Không nên thả diều gần đường dây điện.",explain:"Đúng. Diều vướng dây điện có thể gây điện giật.",answer:!0}]},{questions:[{id:"cn4-dieu-giay-10",type:"mc",q:"Vì sao khung diều nên làm bằng nan tre?",explain:"Nan tre nhẹ, dẻo giúp diều dễ bay lên, ít gãy.",options:["Nặng và cứng","Nhẹ và dẻo","Dễ vỡ"],answer:1},{id:"cn4-dieu-giay-11",type:"mc",q:"Vì sao không thả diều ở lòng đường?",explain:"Lòng đường có xe cộ qua lại, dễ gây tai nạn.",options:["Gió quá to","Dễ gây tai nạn","Diều sẽ đổi màu"],answer:1},{id:"cn4-dieu-giay-12",type:"tf",q:"Đuôi diều giúp diều bay cân, không bị xoay tròn.",explain:"Đúng. Đuôi diều giữ cho diều bay thăng bằng.",answer:!0},{id:"cn4-dieu-giay-13",type:"multi",q:"Khi thả diều, việc nào là đúng?",explain:"Trèo lên mái nhà thả diều dễ bị ngã.",options:["Thả ở bãi đất rộng","Tránh xa dây điện","Trèo lên mái nhà thả","Đi cùng người lớn"],answers:[0,1,3]},{id:"cn4-dieu-giay-14",type:"match",q:"Nối tình huống với cách làm đúng.",explain:"Gặp tình huống nguy hiểm, em không tự xử lí mà nhờ người lớn.",pairs:[["Diều vướng dây điện","Báo người lớn"],["Trời có sấm sét","Thu diều, vào nhà"],["Diều rơi xuống đường","Nhờ người lớn nhặt"]]},{id:"cn4-dieu-giay-15",type:"fill",q:"Diều vướng dây điện, em không tự gỡ mà báo … .",explain:"Người lớn sẽ tìm cách xử lí an toàn.",answer:["người lớn"]},{id:"cn4-dieu-giay-16",type:"order",q:"Sắp xếp các bước làm thân diều.",explain:"Đặt khung, cắt giấy rộng hơn một chút rồi gấp mép dán vào khung.",items:["Đặt khung lên tờ giấy","Cắt giấy rộng hơn khung","Gấp mép giấy, dán vào khung"]},{id:"cn4-dieu-giay-17",type:"tf",q:"Thân diều làm bằng giấy dày, nặng thì diều bay cao hơn.",explain:"Sai. Diều nặng khó bay; nên dùng giấy mỏng, nhẹ.",answer:!1},{id:"cn4-dieu-giay-18",type:"mc",q:"Khung diều cần thế nào để diều bay cân?",explain:"Hai bên khung đều nhau thì diều bay cân.",options:["Hai bên đều nhau","Một bên dài hơn","Thật nặng"],answer:0}]},{questions:[{id:"cn4-dieu-giay-19",type:"mc",q:"Diều của Nam vướng lên dây điện. Nam nên làm gì?",explain:"Trèo cột hay khều diều đều có thể bị điện giật.",options:["Báo người lớn","Lấy gậy khều","Trèo cột gỡ diều"],answer:0},{id:"cn4-dieu-giay-20",type:"multi",q:"Phúc rủ bạn thả diều. Nơi nào KHÔNG nên đến?",explain:"Chỉ bãi cỏ rộng là nơi thả diều an toàn.",options:["Gần đường dây điện","Bên lòng đường","Bãi cỏ rộng","Gần đường tàu"],answers:[0,1,3]},{id:"cn4-dieu-giay-21",type:"tf",q:"Diều cứ xoay tròn rồi rơi, có thể do khung lệch hoặc đuôi quá ngắn.",explain:"Đúng. Khung lệch hoặc đuôi ngắn làm diều mất cân bằng.",answer:!0},{id:"cn4-dieu-giay-22",type:"match",q:"Nối lỗi của diều với cách sửa.",explain:"Sửa đúng chỗ lỗi thì diều bay tốt hơn.",pairs:[["Diều nghiêng một bên","Chỉnh khung cho cân"],["Giấy bị rách","Dán lại giấy"],["Dây diều bị rối","Gỡ rối, quấn lại"]]},{id:"cn4-dieu-giay-23",type:"order",q:"Sắp xếp các bước thu diều.",explain:"Thu dây từ từ, quấn dây, đỡ diều rồi cất nơi khô ráo.",items:["Thu dây chậm cho diều hạ thấp","Quấn dây vào ống","Đỡ diều khi diều xuống","Cất diều nơi khô ráo"]},{id:"cn4-dieu-giay-24",type:"tf",q:"Trời mưa, có sấm sét vẫn nên thả diều cho vui.",explain:"Sai. Có sấm sét phải thu diều, vào nhà ngay.",answer:!1},{id:"cn4-dieu-giay-25",type:"mc",q:"Diều của Ngọc quá nặng, không bay lên. Ngọc nên làm gì?",explain:"Giấy mỏng, nhẹ giúp diều dễ bay lên.",options:["Dùng giấy nhẹ","Dán thêm giấy","Buộc thêm đá"],answer:0},{id:"cn4-dieu-giay-26",type:"fill",q:"Thả diều ở bãi đất …, xa dây điện và đường giao thông.",explain:"Bãi đất rộng là nơi thả diều an toàn.",answer:["rộng"]}]}],challenge:{questions:[{id:"cn4-dieu-giay-08",type:"order",q:"Sắp xếp các bước làm diều.",explain:"Làm khung, dán thân, gắn đuôi rồi buộc dây.",items:["Làm khung bằng nan tre","Dán giấy làm thân diều","Gắn đuôi diều","Buộc dây diều"]},{id:"cn4-dieu-giay-27",type:"mc",q:"Vì sao diều vướng dây điện rất nguy hiểm?",explain:"Chạm vào dây diều đang vướng dây điện có thể bị điện giật.",options:["Diều sẽ hỏng","Bị mắng","Dễ bị điện giật"],answer:2},{id:"cn4-dieu-giay-13",type:"multi",q:"Khi thả diều, việc nào là đúng?",explain:"Trèo lên mái nhà thả diều dễ bị ngã.",options:["Thả ở bãi đất rộng","Tránh xa dây điện","Trèo lên mái nhà thả","Đi cùng người lớn"],answers:[0,1,3]},{id:"cn4-dieu-giay-28",type:"tf",q:"Em có thể làm khung diều nhẹ bằng nan tre mỏng.",explain:"Đúng. Nan tre mỏng nhẹ và dẻo, hợp làm khung diều.",answer:!0},{id:"cn4-dieu-giay-29",type:"match",q:"Nối bộ phận diều với tác dụng.",explain:"Mỗi bộ phận giúp diều bay tốt theo một cách.",pairs:[["Khung diều","Giữ hình dáng diều"],["Đuôi diều","Giúp diều bay cân"],["Dây diều","Giữ, điều khiển diều"]]},{id:"cn4-dieu-giay-30",type:"fill",q:"Bộ phận giữ cho diều có hình dáng là … diều.",explain:"Khung diều làm bằng nan tre, giữ hình dáng diều.",answer:["khung"]},{id:"cn4-dieu-giay-31",type:"mc",q:"Diều đang bay, gió bỗng mạnh giật dây. Em nên làm gì?",explain:"Quấn dây vào tay dễ bị dây cứa đau; em giữ chắc ống dây và thu dần.",options:["Buông tay ngay","Quấn dây vào cổ tay","Giữ chắc, thu dây dần"],answer:2}]},summary:["Diều gồm khung, thân, đuôi và dây diều.","Khung làm bằng nan tre nhẹ, thân bằng giấy mỏng, đuôi giúp diều bay cân.","Thả diều ở bãi đất rộng, xa dây điện; diều vướng dây điện thì báo người lớn."]},{id:"cn4-den-ong-sao",title:"Làm đèn ông sao",weeks:[33,35],learn:[{title:"Đèn ông sao",text:"Đèn ông sao có hình ngôi sao năm cánh, thường được các bạn nhỏ rước vào đêm Tết Trung thu.",example:"⭐ năm cánh · 🌕 Trung thu"},{title:"Bộ phận và vật liệu",text:"Đèn gồm khung sao, giấy bọc ngoài và cán cầm. Khung làm bằng nan tre, giấy bọc là giấy bóng kính màu.",example:"🎋 nan tre · 🟥 giấy bóng kính · 🥢 cán"},{title:"Thắp sáng an toàn",text:"Nên dùng đèn LED nhỏ hoặc đèn pin thay cho nến để không gây cháy. Dùng kéo, dao rọc giấy phải có người lớn giúp.",example:"💡 đèn LED ✅ · 🕯️ nến ⚠️"}],practice:[{questions:[{id:"cn4-den-ong-sao-01",type:"mc",q:"Đèn ông sao có hình gì?",emoji:"⭐",explain:"Đèn ông sao có hình ngôi sao năm cánh.",options:["Hình tròn","Hình vuông","Ngôi sao","Con cá"],answer:2},{id:"cn4-den-ong-sao-02",type:"fill",q:"Đèn ông sao có hình ngôi sao … cánh.",explain:"Đèn ông sao là ngôi sao năm cánh.",answer:["năm","5"]},{id:"cn4-den-ong-sao-03",type:"tf",q:"Nên dùng đèn LED nhỏ thay cho nến trong đèn ông sao.",emoji:"💡",explain:"Đúng. Đèn LED không có lửa nên không gây cháy giấy.",answer:!0},{id:"cn4-den-ong-sao-04",type:"multi",q:"Đèn ông sao gồm những bộ phận nào?",explain:"Đèn ông sao có khung sao, giấy bọc ngoài và cán cầm.",options:["Khung sao","Giấy bọc ngoài","Cán cầm","Bánh xe"],answers:[0,1,2]},{id:"cn4-den-ong-sao-05",type:"mc",q:"Khung đèn ông sao thường làm bằng gì?",explain:"Nan tre nhẹ, dễ uốn, buộc thành khung sao.",options:["Gạch","Thủy tinh","Nan tre","Sắt nặng"],answer:2},{id:"cn4-den-ong-sao-06",type:"tf",q:"Đèn ông sao gắn với Tết Trung thu.",emoji:"🌕",explain:"Đúng. Đêm Trung thu, các bạn nhỏ rước đèn ông sao.",answer:!0},{id:"cn4-den-ong-sao-07",type:"match",q:"Nối bộ phận đèn với vật liệu.",explain:"Khung bằng nan tre, bọc giấy bóng kính, cán là que tre dài.",pairs:[["Khung sao","Nan tre"],["Giấy bọc","Giấy bóng kính"],["Cán cầm","Que tre dài"]]},{id:"cn4-den-ong-sao-08",type:"tf",q:"Dùng dao rọc giấy, em tự làm một mình là an toàn nhất.",explain:"Sai. Dao rọc giấy rất sắc, em cần có người lớn giúp.",answer:!1},{id:"cn4-den-ong-sao-09",type:"order",q:"Sắp xếp các bước làm đèn ông sao.",explain:"Làm khung, bọc giấy, gắn cán rồi trang trí và gắn đèn.",items:["Làm khung ngôi sao","Bọc giấy bóng kính","Gắn cán cầm","Trang trí, gắn đèn LED"]}]},{questions:[{id:"cn4-den-ong-sao-10",type:"mc",q:"Vì sao nên dùng đèn LED thay cho nến?",explain:"Nến có lửa dễ làm giấy bắt cháy; đèn LED an toàn hơn.",options:["Cho đèn nặng hơn","Để đèn tối hơn","Tránh gây cháy"],answer:2},{id:"cn4-den-ong-sao-11",type:"multi",q:"Việc nào giúp làm đèn ông sao an toàn?",explain:"Thắp nến cạnh rèm cửa rất dễ gây cháy.",options:["Có người lớn khi dùng dao","Dùng đèn LED nhỏ","Thắp nến cạnh rèm cửa","Cất kéo sau khi dùng"],answers:[0,1,3]},{id:"cn4-den-ong-sao-12",type:"tf",q:"Giấy bóng kính màu giúp ánh sáng của đèn có màu đẹp.",explain:"Đúng. Ánh sáng đi qua giấy bóng kính màu sẽ có màu của giấy.",answer:!0},{id:"cn4-den-ong-sao-13",type:"match",q:"Nối bước làm với vật liệu dùng.",explain:"Mỗi bước dùng vật liệu phù hợp.",pairs:[["Làm khung","Nan tre, dây buộc"],["Bọc đèn","Giấy bóng kính, hồ dán"],["Trang trí","Tua giấy màu"]]},{id:"cn4-den-ong-sao-14",type:"fill",q:"Để không gây cháy, đèn ông sao nên dùng đèn … nhỏ thay cho nến.",explain:"Đèn LED hoặc đèn pin nhỏ không có lửa nên an toàn.",answer:["LED","led","pin"]},{id:"cn4-den-ong-sao-15",type:"tf",q:"Các cánh sao lệch nhau không làm ảnh hưởng gì đến dáng đèn.",explain:"Sai. Cánh lệch làm đèn méo, không đẹp.",answer:!1},{id:"cn4-den-ong-sao-16",type:"order",q:"Sắp xếp các bước bọc giấy cho đèn.",explain:"Đặt khung lên giấy, cắt theo khung rồi dán.",items:["Đặt khung lên giấy bóng kính","Cắt giấy theo từng phần khung","Phết hồ, dán giấy vào khung"]},{id:"cn4-den-ong-sao-17",type:"mc",q:"Khung sao cần thế nào để đèn đẹp?",explain:"Năm cánh đều nhau thì đèn cân đối, đẹp.",options:["Cánh to cánh nhỏ","Năm cánh đều nhau","Bị cong vẹo"],answer:1},{id:"cn4-den-ong-sao-18",type:"mc",q:"Đêm Trung thu, em rước đèn ở đâu là an toàn?",explain:"Lòng đường có xe, bờ ao bờ sông dễ ngã xuống nước.",options:["Trong sân, ngõ nhỏ","Giữa lòng đường","Bờ ao, bờ sông"],answer:0}]},{questions:[{id:"cn4-den-ong-sao-19",type:"mc",q:"Đèn của Vy bị rách một mảng giấy. Vy nên làm gì?",explain:"Dán miếng giấy mới vào chỗ rách là đèn lại đẹp.",options:["Vứt đèn đi","Dán giấy mới vào","Thắp nến cho sáng"],answer:1},{id:"cn4-den-ong-sao-20",type:"multi",q:"Chi muốn đèn ông sao sáng mà an toàn. Chi chọn gì?",explain:"Nến và bật lửa có lửa, dễ gây cháy đèn giấy.",options:["Đèn LED nhỏ","Đèn pin nhỏ","Cây nến","Bật lửa"],answers:[0,1]},{id:"cn4-den-ong-sao-21",type:"tf",q:"Có thể dùng vật liệu tái chế như que kem, giấy màu cũ để làm đèn.",explain:"Đúng. Dùng vật liệu tái chế vừa tiết kiệm vừa bảo vệ môi trường.",answer:!0},{id:"cn4-den-ong-sao-22",type:"match",q:"Nối lỗi với cách sửa.",explain:"Tìm đúng chỗ lỗi rồi sửa ở chỗ đó.",pairs:[["Cánh sao bị lệch","Buộc lại cho đều"],["Giấy bị bong","Dán lại bằng hồ"],["Cán bị lỏng","Buộc chặt cán"]]},{id:"cn4-den-ong-sao-23",type:"tf",q:"Thấy giấy đèn bén lửa, em nên tự dập bằng tay.",explain:"Sai. Dập bằng tay dễ bị bỏng; em tránh xa và báo ngay người lớn.",answer:!1},{id:"cn4-den-ong-sao-24",type:"order",q:"Sắp xếp các việc sau đêm rước đèn.",explain:"Tắt đèn, tháo pin rồi cất đèn nơi khô ráo để dùng lại.",items:["Tắt đèn LED","Tháo pin ra","Cất đèn nơi khô ráo"]},{id:"cn4-den-ong-sao-25",type:"mc",q:"Nam muốn đèn có nhiều màu. Nam làm thế nào?",explain:"Mỗi phần dán một màu giấy bóng kính thì đèn có nhiều màu.",options:["Dán giấy nhiều màu","Thắp thêm nến","Bỏ hết giấy bọc"],answer:0},{id:"cn4-den-ong-sao-26",type:"fill",q:"Khi dùng dao rọc giấy, em cần có … lớn giúp.",explain:"Dao rọc giấy sắc, cần người lớn giúp.",answer:["người"]}]}],challenge:{questions:[{id:"cn4-den-ong-sao-09",type:"order",q:"Sắp xếp các bước làm đèn ông sao.",explain:"Làm khung, bọc giấy, gắn cán rồi trang trí và gắn đèn.",items:["Làm khung ngôi sao","Bọc giấy bóng kính","Gắn cán cầm","Trang trí, gắn đèn LED"]},{id:"cn4-den-ong-sao-27",type:"mc",q:"Vì sao không nên thắp nến trong đèn giấy?",explain:"Lửa nến dễ làm giấy bắt cháy.",options:["Nến làm đèn nặng","Dễ gây cháy","Nến quá sáng"],answer:1},{id:"cn4-den-ong-sao-11",type:"multi",q:"Việc nào giúp làm đèn ông sao an toàn?",explain:"Thắp nến cạnh rèm cửa rất dễ gây cháy.",options:["Có người lớn khi dùng dao","Dùng đèn LED nhỏ","Thắp nến cạnh rèm cửa","Cất kéo sau khi dùng"],answers:[0,1,3]},{id:"cn4-den-ong-sao-28",type:"tf",q:"Đèn ông sao là đồ chơi dân gian của trẻ em Việt Nam.",explain:"Đúng. Đèn ông sao là đồ chơi dân gian gắn với Tết Trung thu.",answer:!0},{id:"cn4-den-ong-sao-29",type:"match",q:"Nối đồ chơi với bộ phận của nó.",explain:"Mỗi đồ chơi dân gian có bộ phận riêng.",pairs:[["Đèn ông sao","Khung sao năm cánh"],["Diều","Đuôi diều"],["Chong chóng","Cánh hứng gió"]]},{id:"cn4-den-ong-sao-30",type:"fill",q:"Giấy trong, có màu, dùng bọc đèn ông sao là giấy bóng … .",explain:"Giấy bóng kính trong, có màu, cho ánh sáng đi qua.",answer:["kính"]},{id:"cn4-den-ong-sao-31",type:"mc",q:"Trước khi làm đèn, việc đầu tiên nên làm là gì?",explain:"Chuẩn bị đủ vật liệu, dụng cụ rồi mới bắt đầu làm.",options:["Gắn cán cầm","Chuẩn bị đồ","Bọc giấy màu"],answer:1}]},summary:["Đèn ông sao có hình ngôi sao năm cánh, gắn với Tết Trung thu.","Đèn gồm khung nan tre, giấy bóng kính bọc ngoài và cán cầm.","Dùng đèn LED thay nến; dùng dao, kéo phải có người lớn giúp."]}]}],a={grade:4,subject:n,title:h,review:i,cid:t,topics:c};export{t as cid,a as default,g as grade,i as review,n as subject,h as title,c as topics};
